(function (root) {
  'use strict';
  var TR = root.CALR_TRANS = root.CALR_TRANS || {};

  TR['CN-LAW-0207'] = {
    "lawId": "CN-LAW-0207",
    "sourceLang": "zh",
    "targetLang": "en",
    "engine": "llm",
    "model": "deepseek-v4.1-flash",
    "promptVersion": "calr-trans-v2",
    "translatedAt": "2026-10-14",
    "reviewed": "machine",
    "glossaryVersion": "calr-terms-2026-10-v2",
    "completenessNote": "逐条对译，共 306 条；条号与官方原文一一对应，未合并、未省略。",
    "articles": [
      {
        "no": 1,
        "text": {
          "en": "The Civil Procedure Law of the People's Republic of China is enacted on the basis of the Constitution and in the light of the experience and practical conditions of the civil adjudication work of our country."
        },
        "noLabel": {
          "en": "Article 1."
        }
      },
      {
        "no": 2,
        "text": {
          "en": "The tasks of the Civil Procedure Law of the People's Republic of China are to protect the parties in exercising their litigation rights, ensure that the people's courts ascertain the facts, distinguish right from wrong, correctly apply the law, try civil cases promptly, affirm civil rights and obligations, sanction civil violations, protect the lawful rights and interests of the parties, educate citizens to consciously abide by the law, maintain the social order and the economic order, and ensure the smooth progress of the cause of socialist construction."
        },
        "noLabel": {
          "en": "Article 2."
        }
      },
      {
        "no": 3,
        "text": {
          "en": "The provisions of this Law shall apply to civil actions accepted by the people's courts arising from disputes over property relations and personal relations between citizens, between legal persons, between other organisations, and among citizens, legal persons and other organisations."
        },
        "noLabel": {
          "en": "Article 3."
        }
      },
      {
        "no": 4,
        "text": {
          "en": "All those who engage in civil litigation within the territory of the People's Republic of China must comply with this Law."
        },
        "noLabel": {
          "en": "Article 4."
        }
      },
      {
        "no": 5,
        "text": {
          "en": "Foreign nationals, stateless persons and foreign enterprises and organisations that file a lawsuit or respond to an action in a people's court shall have the same litigation rights and obligations as citizens, legal persons and other organisations of the People's Republic of China.\nWhere a foreign court imposes restrictions on the civil litigation rights of citizens, legal persons and other organisations of the People's Republic of China, the people's courts of the People's Republic of China shall apply the principle of reciprocity to the civil litigation rights of the citizens, enterprises and organisations of that country."
        },
        "noLabel": {
          "en": "Article 5."
        }
      },
      {
        "no": 6,
        "text": {
          "en": "The power of adjudication over civil cases shall be exercised by the people's courts.\nThe people's courts shall exercise adjudicative power independently in trying civil cases in accordance with the provisions of law, and shall not be subject to interference by administrative organs, public organisations or individuals."
        },
        "noLabel": {
          "en": "Article 6."
        }
      },
      {
        "no": 7,
        "text": {
          "en": "In trying civil cases, the people's courts must take the facts as the basis and the law as the criterion."
        },
        "noLabel": {
          "en": "Article 7."
        }
      },
      {
        "no": 8,
        "text": {
          "en": "The parties to civil litigation shall have equal litigation rights. In trying civil cases, the people's courts shall guarantee and facilitate the parties' exercise of litigation rights and shall treat all parties equally in the application of the law."
        },
        "noLabel": {
          "en": "Article 8."
        }
      },
      {
        "no": 9,
        "text": {
          "en": "In trying civil cases, the people's courts shall conduct mediation in accordance with the principles of voluntariness and lawfulness; where mediation fails, judgment shall be rendered promptly."
        },
        "noLabel": {
          "en": "Article 9."
        }
      },
      {
        "no": 10,
        "text": {
          "en": "In trying civil cases, the people's courts shall, in accordance with the provisions of law, apply the systems of collegial panel, challenge, public trial and the system of two instances constituting final adjudication."
        },
        "noLabel": {
          "en": "Article 10."
        }
      },
      {
        "no": 11,
        "text": {
          "en": "Citizens of all ethnic groups shall have the right to conduct civil litigation in the spoken and written languages of their own ethnic groups.\nIn areas where ethnic minorities live in concentrated communities or where two or more ethnic groups live together, the people's courts shall conduct trials and issue legal documents in the spoken and written languages commonly used in the area.\nThe people's courts shall provide translation for participants in proceedings who do not understand the spoken and written languages commonly used in the area."
        },
        "noLabel": {
          "en": "Article 11."
        }
      },
      {
        "no": 12,
        "text": {
          "en": "When the people's courts try civil cases, the parties shall have the right to engage in debate."
        },
        "noLabel": {
          "en": "Article 12."
        }
      },
      {
        "no": 13,
        "text": {
          "en": "Civil litigation shall follow the principle of good faith.\nThe parties shall have the right, within the scope provided by law, to dispose of their civil rights and litigation rights."
        },
        "noLabel": {
          "en": "Article 13."
        }
      },
      {
        "no": 14,
        "text": {
          "en": "The people's procuratorates shall have the right to exercise legal supervision over civil litigation."
        },
        "noLabel": {
          "en": "Article 14."
        }
      },
      {
        "no": 15,
        "text": {
          "en": "Where an act harms the civil rights and interests of the State, a collective or an individual, an organ, public organisation, enterprise or institution may support the injured unit or individual in filing a lawsuit in a people's court."
        },
        "noLabel": {
          "en": "Article 15."
        }
      },
      {
        "no": 16,
        "text": {
          "en": "With the consent of the parties, civil litigation activities may be conducted online through information network platforms.\nWhere civil litigation activities are conducted online through information network platforms, they shall have the same legal effect as offline litigation activities."
        },
        "noLabel": {
          "en": "Article 16."
        }
      },
      {
        "no": 17,
        "text": {
          "en": "The people's congresses of ethnic autonomous areas may, in accordance with the principles of the Constitution and of this Law and in the light of the specific conditions of the local ethnic groups, formulate specific provisions with appropriate adaptations or supplementary provisions. The provisions of an autonomous region shall be submitted to the Standing Committee of the National People's Congress for approval. The provisions of an autonomous prefecture or autonomous county shall be submitted to the standing committee of the people's congress of the province or autonomous region for approval and filed with the Standing Committee of the National People's Congress for the record."
        },
        "noLabel": {
          "en": "Article 17."
        }
      },
      {
        "no": 18,
        "text": {
          "en": "Primary people's courts shall have jurisdiction over civil cases of first instance, except as otherwise provided in this Law."
        },
        "noLabel": {
          "en": "Article 18."
        },
        "chapter": {
          "en": "Section 1 Hierarchical Jurisdiction"
        }
      },
      {
        "no": 19,
        "text": {
          "en": "Intermediate people's courts shall have jurisdiction over the following civil cases of first instance:\n(a) major foreign-related cases;\n(b) cases that have a major impact in the area under their jurisdiction; and\n(c) cases that the Supreme People's Court determines shall be under the jurisdiction of intermediate people's courts."
        },
        "noLabel": {
          "en": "Article 19."
        },
        "chapter": {
          "en": "Section 1 Hierarchical Jurisdiction"
        }
      },
      {
        "no": 20,
        "text": {
          "en": "Higher people's courts shall have jurisdiction over civil cases of first instance that have a major impact in the area under their jurisdiction."
        },
        "noLabel": {
          "en": "Article 20."
        },
        "chapter": {
          "en": "Section 1 Hierarchical Jurisdiction"
        }
      },
      {
        "no": 21,
        "text": {
          "en": "The Supreme People's Court shall have jurisdiction over the following civil cases of first instance:\n(a) cases that have a major impact throughout the country; and\n(b) cases that it considers should be tried by the court itself."
        },
        "noLabel": {
          "en": "Article 21."
        },
        "chapter": {
          "en": "Section 1 Hierarchical Jurisdiction"
        }
      },
      {
        "no": 22,
        "text": {
          "en": "A civil action brought against a citizen shall be under the jurisdiction of the people's court at the place of the defendant's domicile; where the defendant's domicile is different from the place of his habitual residence, the action shall be under the jurisdiction of the people's court at the place of his habitual residence.\nA civil action brought against a legal person or other organisation shall be under the jurisdiction of the people's court at the place of the defendant's domicile.\nWhere the places of domicile or habitual residence of several defendants in the same action are located within the areas under the jurisdiction of two or more people's courts, each of those people's courts shall have jurisdiction."
        },
        "noLabel": {
          "en": "Article 22."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 23,
        "text": {
          "en": "The following civil actions shall be under the jurisdiction of the people's court at the place of the plaintiff's domicile; where the plaintiff's domicile is different from the place of his habitual residence, the action shall be under the jurisdiction of the people's court at the place of his habitual residence:\n(a) actions concerning personal status brought against a person who does not reside within the territory of the People's Republic of China;\n(b) actions concerning personal status brought against a person who is missing or in respect of whom a declaration of disappearance has been made;\n(c) actions brought against a person who is subject to compulsory educational measures; and\n(d) actions brought against a person who is imprisoned."
        },
        "noLabel": {
          "en": "Article 23."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 24,
        "text": {
          "en": "An action brought on the basis of a contract dispute shall be under the jurisdiction of the people's court at the place of the defendant's domicile or at the place of performance of the contract."
        },
        "noLabel": {
          "en": "Article 24."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 25,
        "text": {
          "en": "An action brought on the basis of an insurance contract dispute shall be under the jurisdiction of the people's court at the place of the defendant's domicile or at the place where the subject matter of the insurance is located."
        },
        "noLabel": {
          "en": "Article 25."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 26,
        "text": {
          "en": "An action brought on the basis of a dispute over an instrument shall be under the jurisdiction of the people's court at the place of payment of the instrument or at the place of the defendant's domicile."
        },
        "noLabel": {
          "en": "Article 26."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 27,
        "text": {
          "en": "An action brought on the basis of a dispute concerning the establishment of a company, the confirmation of shareholder qualification, profit distribution, dissolution or other such matters shall be under the jurisdiction of the people's court at the place of domicile of the company."
        },
        "noLabel": {
          "en": "Article 27."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 28,
        "text": {
          "en": "An action brought on the basis of a dispute over a railway, road, water or air transport contract or a combined transport contract shall be under the jurisdiction of the people's court at the place of departure or destination of transport or at the place of the defendant's domicile."
        },
        "noLabel": {
          "en": "Article 28."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 29,
        "text": {
          "en": "An action brought on the basis of a tortious act shall be under the jurisdiction of the people's court at the place where the tortious act is committed or at the place of the defendant's domicile."
        },
        "noLabel": {
          "en": "Article 29."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 30,
        "text": {
          "en": "An action brought to claim damages on the basis of a railway, road, water or air accident shall be under the jurisdiction of the people's court at the place where the accident occurred, the place where the vehicle or ship first arrived or where the aircraft first landed, or the place of the defendant's domicile."
        },
        "noLabel": {
          "en": "Article 30."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 31,
        "text": {
          "en": "An action brought to claim damages for a collision of ships or any other maritime damage accident shall be under the jurisdiction of the people's court at the place where the collision occurred, at the place where the colliding ship first arrived, at the place where the ship that caused the damage was detained, or at the place of the defendant's domicile."
        },
        "noLabel": {
          "en": "Article 31."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 32,
        "text": {
          "en": "An action brought to claim payment of expenses for salvage at sea shall be under the jurisdiction of the people's court at the place where the salvage was carried out or at the place where the salvaged ship first arrived."
        },
        "noLabel": {
          "en": "Article 32."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 33,
        "text": {
          "en": "An action brought in respect of general average shall be under the jurisdiction of the people's court at the place where the ship first arrived, at the place where the general average was adjusted, or at the place where the voyage terminated."
        },
        "noLabel": {
          "en": "Article 33."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 34,
        "text": {
          "en": "The following cases shall be under the exclusive jurisdiction of the people's courts prescribed in this Article:\n(a) an action brought in respect of a dispute over immovable property shall be under the jurisdiction of the people's court at the place where the immovable property is located;\n(b) an action brought in respect of a dispute arising from port operations shall be under the jurisdiction of the people's court at the place where the port is located; and\n(c) an action brought in respect of a dispute over succession to an estate shall be under the jurisdiction of the people's court at the place of the decedent's domicile at the time of death or at the place where the principal part of the estate is located."
        },
        "noLabel": {
          "en": "Article 34."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 35,
        "text": {
          "en": "The parties to a dispute over a contract or over any other property rights and interests may, by written agreement, choose the people's court at the place of the defendant's domicile, the place of performance of the contract, the place of conclusion of the contract, the place of the plaintiff's domicile, the place where the subject matter is located, or any other place actually connected with the dispute, to exercise jurisdiction, provided that the provisions of this Law on hierarchical jurisdiction and exclusive jurisdiction are not violated."
        },
        "noLabel": {
          "en": "Article 35."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 36,
        "text": {
          "en": "Where two or more people's courts have jurisdiction over an action, the plaintiff may file the lawsuit in one of them; where the plaintiff files the lawsuit in two or more people's courts that have jurisdiction, the case shall be under the jurisdiction of the people's court that first placed the case on file."
        },
        "noLabel": {
          "en": "Article 36."
        },
        "chapter": {
          "en": "Section 2 Territorial Jurisdiction"
        }
      },
      {
        "no": 37,
        "text": {
          "en": "Where a people's court discovers that a case it has accepted does not fall within its jurisdiction, it shall transfer the case to the people's court that has jurisdiction, and the people's court to which the case is transferred shall accept the case. Where the people's court to which the case is transferred finds that, in accordance with the provisions, the transferred case does not fall within its jurisdiction, it shall report the matter to a people's court at a higher level for the designation of jurisdiction and shall not transfer the case again on its own."
        },
        "noLabel": {
          "en": "Article 37."
        },
        "chapter": {
          "en": "Section 3 Transfer and Designation of Jurisdiction"
        }
      },
      {
        "no": 38,
        "text": {
          "en": "Where a people's court that has jurisdiction is unable to exercise jurisdiction because of special reasons, a people's court at a higher level shall designate jurisdiction.\nWhere a dispute over jurisdiction arises between people's courts, it shall be resolved by the parties to the dispute through consultation; where consultation fails to resolve the dispute, the matter shall be reported to their common people's court at a higher level for the designation of jurisdiction."
        },
        "noLabel": {
          "en": "Article 38."
        },
        "chapter": {
          "en": "Section 3 Transfer and Designation of Jurisdiction"
        }
      },
      {
        "no": 39,
        "text": {
          "en": "A people's court at a higher level shall have the power to try civil cases of first instance over which a people's court at a lower level has jurisdiction; where it is indeed necessary to transfer a civil case of first instance over which it has jurisdiction to a people's court at a lower level for trial, the matter shall be reported to the people's court at a higher level for approval.\nWhere a people's court at a lower level finds that a civil case of first instance over which it has jurisdiction needs to be tried by a people's court at a higher level, it may report the matter to the people's court at a higher level for trial."
        },
        "noLabel": {
          "en": "Article 39."
        },
        "chapter": {
          "en": "Section 3 Transfer and Designation of Jurisdiction"
        }
      },
      {
        "no": 40,
        "text": {
          "en": "Civil cases of first instance shall be tried by a collegial panel composed of judges and people's assessors or of judges alone. The number of members of a collegial panel shall be odd.\nCivil cases tried under the summary procedure shall be tried by a single judge. For a civil case of first instance tried by a primary people's court in which the basic facts are clear and the rights and obligations are definite, a single judge may try the case under the ordinary procedure.\nWhen participating in trial activities, people's assessors shall have the same rights and obligations as judges, except as otherwise provided by law."
        },
        "noLabel": {
          "en": "Article 40."
        },
        "chapter": {
          "en": "Chapter III Trial Organisation"
        }
      },
      {
        "no": 41,
        "text": {
          "en": "Civil cases of second instance shall be tried by a collegial panel composed of judges. The number of members of a collegial panel shall be odd.\nFor a civil case of second instance that was concluded at first instance under the summary procedure or in which an appeal was lodged against an order, where the facts are clear and the rights and obligations are definite, a single judge may try the case with the consent of both parties.\nFor a case remanded for retrial, the people's court that originally tried the case shall form a new collegial panel in accordance with the procedure of first instance.\nFor the trial of a retrial case, where the case was originally tried at first instance, a new collegial panel shall be formed in accordance with the procedure of first instance; where the case was originally tried at second instance or was brought up for trial by a people's court at a higher level, a new collegial panel shall be formed in accordance with the procedure of second instance."
        },
        "noLabel": {
          "en": "Article 41."
        },
        "chapter": {
          "en": "Chapter III Trial Organisation"
        }
      },
      {
        "no": 42,
        "text": {
          "en": "People's courts shall not try the following civil cases by a single judge:\n(a) cases involving State interests or the public interests of the society;\n(b) cases involving group disputes that may affect social stability;\n(c) cases that have attracted widespread attention of the people or have had a relatively major social impact;\n(d) cases of a new type or that are difficult or complex;\n(e) cases that should be tried by a collegial panel as provided by law; or\n(f) other cases that are not suitable for trial by a single judge."
        },
        "noLabel": {
          "en": "Article 42."
        },
        "chapter": {
          "en": "Chapter III Trial Organisation"
        }
      },
      {
        "no": 43,
        "text": {
          "en": "Where, in the course of trial, a people's court finds that a case is not suitable for trial by a single judge, it shall order the transfer of the case to a collegial panel for trial.\nWhere a party considers that the trial of the case by a single judge violates the provisions of law, he may raise an objection to the people's court. The people's court shall examine the objection raised by the party; where the objection is upheld, it shall order the transfer of the case to a collegial panel for trial; where the objection is not upheld, it shall issue an order rejecting the objection."
        },
        "noLabel": {
          "en": "Article 43."
        },
        "chapter": {
          "en": "Chapter III Trial Organisation"
        }
      },
      {
        "no": 44,
        "text": {
          "en": "The presiding judge of a collegial panel shall be a judge designated by the president or the head of a division of the people's court; where the president or the head of a division participates in the trial, he shall serve as the presiding judge."
        },
        "noLabel": {
          "en": "Article 44."
        },
        "chapter": {
          "en": "Chapter III Trial Organisation"
        }
      },
      {
        "no": 45,
        "text": {
          "en": "A collegial panel shall deliberate on a case under the principle that the minority shall be subordinate to the majority. The deliberation shall be recorded in writing, and the members of the collegial panel shall sign the record. The dissenting opinions expressed in the deliberation must be truthfully entered in the record."
        },
        "noLabel": {
          "en": "Article 45."
        },
        "chapter": {
          "en": "Chapter III Trial Organisation"
        }
      },
      {
        "no": 46,
        "text": {
          "en": "Judges shall handle cases impartially in accordance with the law.\nJudges shall not accept dinner invitations or gifts from the parties or their agents ad litem.\nWhere a judge commits an act of corruption or acceptance of bribes, malpractices for personal gain, or perverting the law in rendering judgment, his legal liability shall be investigated; where the act constitutes a crime, criminal responsibility shall be investigated in accordance with the law."
        },
        "noLabel": {
          "en": "Article 46."
        },
        "chapter": {
          "en": "Chapter III Trial Organisation"
        }
      },
      {
        "no": 47,
        "text": {
          "en": "Where any of the following circumstances applies, a judge shall challenge himself or herself, and the parties shall have the right to apply orally or in writing for the challenge of the judge:\n(a) the judge is a party to the case or a close relative of a party or an agent ad litem;\n(b) the judge has an interest in the case; or\n(c) the judge has any other relationship with a party or an agent ad litem in the case, which may affect the fair trial of the case.\nWhere a judge accepts dinner invitations or gifts from a party or an agent ad litem, or meets a party or an agent ad litem in violation of the relevant provisions, the parties shall have the right to demand the challenge of the judge.\nWhere a judge commits any of the acts prescribed in the preceding paragraph, his legal liability shall be investigated in accordance with the law.\nThe provisions of the preceding three paragraphs shall apply to judge assistants, court clerks, judicial technical personnel, translators, appraisers and inspectors."
        },
        "noLabel": {
          "en": "Article 47."
        },
        "chapter": {
          "en": "Chapter IV Recusal"
        }
      },
      {
        "no": 48,
        "text": {
          "en": "Where a party applies for the challenge of a judge, he shall state the reasons, and the application shall be made when the trial of the case begins; where the ground for the challenge becomes known after the trial of the case has begun, the application may also be made before the conclusion of the court debate.\nBefore a people's court makes a decision on the application for challenge, the person against whom the application is made shall suspend his participation in the work of the case, except where the case requires the adoption of emergency measures."
        },
        "noLabel": {
          "en": "Article 48."
        },
        "chapter": {
          "en": "Chapter IV Recusal"
        }
      },
      {
        "no": 49,
        "text": {
          "en": "The challenge of the president of a court when he serves as the presiding judge or the single judge shall be decided by the adjudication committee; the challenge of any other judge shall be decided by the president of the court; and the challenge of any other person shall be decided by the presiding judge or the single judge."
        },
        "noLabel": {
          "en": "Article 49."
        },
        "chapter": {
          "en": "Chapter IV Recusal"
        }
      },
      {
        "no": 50,
        "text": {
          "en": "A people's court shall make a decision, orally or in writing, within three days from the date on which a party applies for the challenge of a judge. Where the applicant refuses to accept the decision, he may apply for reconsideration once at the time when he is notified of the decision. During the period of reconsideration, the person against whom the application for challenge is made shall not stop participating in the work of the case. The people's court shall make a decision on the application for reconsideration within three days and notify the applicant for reconsideration."
        },
        "noLabel": {
          "en": "Article 50."
        },
        "chapter": {
          "en": "Chapter IV Recusal"
        }
      },
      {
        "no": 51,
        "text": {
          "en": "Citizens, legal persons and other organisations may act as parties to civil litigation.\nA legal person shall file a lawsuit through its legal representative. Another organisation shall file a lawsuit through its principal person in charge."
        },
        "noLabel": {
          "en": "Article 51."
        },
        "chapter": {
          "en": "Section 1 Parties"
        }
      },
      {
        "no": 52,
        "text": {
          "en": "A party shall have the right to entrust an agent ad litem, apply for the challenge of a judge, collect and present evidence, engage in debate, request mediation, file an appeal and apply for enforcement.\nA party may consult the materials related to the case and may make copies of the said materials and the litigation documents. The scope of and measures for consulting and copying the materials related to the case shall be provided by the Supreme People's Court.\nA party must exercise his litigation rights in accordance with the law, comply with the litigation order, and perform the written judgment, written order and written mediation agreement that have become legally effective."
        },
        "noLabel": {
          "en": "Article 52."
        },
        "chapter": {
          "en": "Section 1 Parties"
        }
      },
      {
        "no": 53,
        "text": {
          "en": "The two parties may reach a settlement of their own accord."
        },
        "noLabel": {
          "en": "Article 53."
        },
        "chapter": {
          "en": "Section 1 Parties"
        }
      },
      {
        "no": 54,
        "text": {
          "en": "The plaintiff may waive or alter his claims. The defendant may admit or refute the claims and shall have the right to file a counterclaim."
        },
        "noLabel": {
          "en": "Article 54."
        },
        "chapter": {
          "en": "Section 1 Parties"
        }
      },
      {
        "no": 55,
        "text": {
          "en": "Where one or both parties to an action consist of two or more persons and the subject matter of the action is common, or the subject matters of the action are of the same type and the people's court finds that the claims may be joined and the parties consent thereto, the action is a joint action.\nWhere the joint litigants on one side have common rights and obligations in respect of the subject matter of the action, the litigation conduct of one of them shall be binding on the other joint litigants upon their recognition; where the joint litigants on one side have no common rights and obligations in respect of the subject matter of the action, the litigation conduct of one of them shall not be binding on the other joint litigants."
        },
        "noLabel": {
          "en": "Article 55."
        },
        "chapter": {
          "en": "Section 1 Parties"
        }
      },
      {
        "no": 56,
        "text": {
          "en": "Where one party to a joint action consists of a large number of persons, the action may be brought by representatives elected by the parties. The litigation conduct of a representative shall be binding on the parties he represents; however, where a representative alters or waives the claims, admits the claims of the opposing party, or reaches a settlement, he must obtain the consent of the parties he represents."
        },
        "noLabel": {
          "en": "Article 56."
        },
        "chapter": {
          "en": "Section 1 Parties"
        }
      },
      {
        "no": 57,
        "text": {
          "en": "Where the subject matters of an action are of the same type, one party consists of a large number of persons and the number of persons is not yet determined at the time of filing the lawsuit, the people's court may issue a public notice stating the circumstances of the case and the claims, and notify the holders of rights to register with the people's court within a specified period.\nThe holders of rights who have registered with the people's court may elect representatives to file the lawsuit; where no representative can be elected, the people's court may agree with the registered holders of rights on a representative.\nThe litigation conduct of a representative shall be binding on the parties he represents; however, where a representative alters or waives the claims, admits the claims of the opposing party, or reaches a settlement, he must obtain the consent of the parties he represents.\nA judgment or order rendered by a people's court shall be binding on all the holders of rights who have registered. Where a holder of rights who has not registered files a lawsuit within the limitation period, the judgment or order shall apply."
        },
        "noLabel": {
          "en": "Article 57."
        },
        "chapter": {
          "en": "Section 1 Parties"
        }
      },
      {
        "no": 58,
        "text": {
          "en": "For an act harming the public interests of the society, such as polluting the environment or infringing the lawful rights and interests of a large number of consumers, an organ or a relevant organisation prescribed by law may file a lawsuit in a people's court.\nWhere, in the course of performing its duties, a people's procuratorate discovers an act harming the public interests of the society, such as undermining the ecological environment and resource protection, or infringing the lawful rights and interests of a large number of consumers in the field of food and drug safety, and there is no organ or organisation prescribed in the preceding paragraph or the organ or organisation prescribed in the preceding paragraph does not file a lawsuit, it may file a lawsuit in a people's court. Where the organ or organisation prescribed in the preceding paragraph files a lawsuit, the people's procuratorate may support the bringing of the action."
        },
        "noLabel": {
          "en": "Article 58."
        },
        "chapter": {
          "en": "Section 1 Parties"
        }
      },
      {
        "no": 59,
        "text": {
          "en": "Where a third party considers that it has an independent right to the subject matter of the action between the two parties, it shall have the right to file a lawsuit.\nWhere a third party has no independent right to the subject matter of the action between the two parties, but the outcome of the case has a legal interest for it, it may apply to participate in the action, or the people's court may notify it to participate in the action. A third party whom a people's court orders to bear civil liability shall have the litigation rights and obligations of a party.\nWhere a third party prescribed in the preceding two paragraphs fails to participate in the action for reasons not attributable to itself, but there is evidence proving that part or all of the contents of a legally effective judgment, order or mediation agreement are erroneous and harm its civil rights and interests, it may, within six months from the day on which it knew or should have known that its civil rights and interests were harmed, file a lawsuit in the people's court that rendered the judgment, order or mediation agreement. Where, after trial, the people's court finds the claims upheld, it shall alter or rescind the original judgment, order or mediation agreement; where the claims are not upheld, it shall reject the claims."
        },
        "noLabel": {
          "en": "Article 59."
        },
        "chapter": {
          "en": "Section 1 Parties"
        }
      },
      {
        "no": 60,
        "text": {
          "en": "A person without capacity to file a lawsuit shall be represented in the action by his guardian as statutory agent. Where the statutory agents shift the responsibility of representation onto each other, the people's court shall designate one of them to file the lawsuit on behalf of the person."
        },
        "noLabel": {
          "en": "Article 60."
        },
        "chapter": {
          "en": "Section 2 Agents ad Litem"
        }
      },
      {
        "no": 61,
        "text": {
          "en": "A party or his statutory agent may entrust one or two persons to act as agents ad litem.\nThe following persons may be entrusted as agents ad litem:\n(a) lawyers and grassroots legal service workers;\n(b) close relatives or staff members of the party; or\n(c) citizens recommended by the community or the unit to which the party belongs or by the relevant social organisations."
        },
        "noLabel": {
          "en": "Article 61."
        },
        "chapter": {
          "en": "Section 2 Agents ad Litem"
        }
      },
      {
        "no": 62,
        "text": {
          "en": "Where a party entrusts another person to conduct the action on his behalf, he must submit to the people's court a power of attorney signed or sealed by the principal.\nThe power of attorney must state the matters entrusted and the scope of authority. Where an agent ad litem is to admit, waive or alter the claims of the party, reach a settlement, or file a counterclaim or an appeal on the party's behalf, the special authorisation of the principal must be obtained.\nWhere a citizen of the People's Republic of China residing abroad mails a power of attorney from abroad or delivers it through another person, the power of attorney must be certified by the embassy or consulate of the People's Republic of China in that country; where there is no embassy or consulate in that country, it must be certified by the embassy or consulate in that country of a third State having diplomatic relations with the People's Republic of China, then certified by the embassy or consulate of the People's Republic of China in that third State, or certified by a local patriotic overseas Chinese organisation."
        },
        "noLabel": {
          "en": "Article 62."
        },
        "chapter": {
          "en": "Section 2 Agents ad Litem"
        }
      },
      {
        "no": 63,
        "text": {
          "en": "Where the scope of authority of an agent ad litem is altered or terminated, the party shall notify the people's court in writing, and the people's court shall notify the opposing party."
        },
        "noLabel": {
          "en": "Article 63."
        },
        "chapter": {
          "en": "Section 2 Agents ad Litem"
        }
      },
      {
        "no": 64,
        "text": {
          "en": "A lawyer or any other agent ad litem acting in an action shall have the right to investigate and collect evidence and may consult the materials related to the case. The scope of and measures for consulting the materials related to the case shall be provided by the Supreme People's Court."
        },
        "noLabel": {
          "en": "Article 64."
        },
        "chapter": {
          "en": "Section 2 Agents ad Litem"
        }
      },
      {
        "no": 65,
        "text": {
          "en": "In a divorce case in which a party has an agent ad litem, the party himself shall still appear in court, except where he is unable to express his intention; where he is genuinely unable to appear in court because of special circumstances, he must submit a written opinion to the people's court."
        },
        "noLabel": {
          "en": "Article 65."
        },
        "chapter": {
          "en": "Section 2 Agents ad Litem"
        }
      },
      {
        "no": 66,
        "text": {
          "en": "Evidence includes:\n(a) statements of the parties;\n(b) documentary evidence;\n(c) physical evidence;\n(d) audio-visual materials;\n(e) electronic data;\n(f) testimony of witnesses;\n(g) expert opinions; and\n(h) records of inquests.\nEvidence must be investigated and verified as true before it can serve as the basis for ascertaining the facts."
        },
        "noLabel": {
          "en": "Article 66."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 67,
        "text": {
          "en": "A party shall have the burden of presenting evidence for its own assertions.\nThe people's court shall investigate and collect evidence that a party and his agent ad litem are unable to collect on their own for objective reasons or that the people's court considers necessary for the trial of the case.\nThe people's court shall, in accordance with the statutory procedure, examine and verify evidence in a comprehensive and objective manner."
        },
        "noLabel": {
          "en": "Article 67."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 68,
        "text": {
          "en": "A party shall present evidence for its own assertions in a timely manner.\nThe people's court shall, on the basis of the assertions of the party and the circumstances of the trial of the case, determine the evidence to be presented by the party and the time period for presenting it. Where the party has genuine difficulty in presenting evidence within the said time period, it may apply to the people's court for an extension of the time period, and the people's court shall appropriately extend the time period upon the party's application. Where a party presents evidence after the expiry of the time period, the people's court shall order it to state the reasons; where the party refuses to state the reasons or the reasons are untenable, the people's court may, in light of the different circumstances, refuse to admit the evidence or admit the evidence but reprimand or fine the party."
        },
        "noLabel": {
          "en": "Article 68."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 69,
        "text": {
          "en": "When a people's court receives evidentiary materials submitted by a party, it shall issue a receipt stating the name of the evidence, the number of pages, the number of copies, whether the evidence is in the original or in photocopy, the time of receipt and other such matters, and the receipt shall be signed or sealed by the personnel who handled the matter."
        },
        "noLabel": {
          "en": "Article 69."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 70,
        "text": {
          "en": "A people's court shall have the power to investigate and collect evidence from the relevant units and individuals, and the relevant units and individuals shall not refuse.\nThe people's court shall distinguish the true from the false in respect of the certificates issued by the relevant units and individuals and examine and determine their validity."
        },
        "noLabel": {
          "en": "Article 70."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 71,
        "text": {
          "en": "Evidence shall be presented in court, and the parties shall conduct examination of evidence. Evidence involving State secrets, trade secrets or personal privacy shall be kept confidential; where such evidence needs to be presented in court, it shall not be presented in open court."
        },
        "noLabel": {
          "en": "Article 71."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 72,
        "text": {
          "en": "Legal facts and documents certified through notarisation in accordance with the statutory procedure shall be taken by the people's court as the basis for ascertaining the facts, unless there is contrary evidence sufficient to refute the notarial certificate."
        },
        "noLabel": {
          "en": "Article 72."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 73,
        "text": {
          "en": "Documentary evidence shall be submitted in the original, and physical evidence shall be submitted as the original object. Where it is genuinely difficult to submit the original or the original object, reproductions, photographs, duplicates or extracts may be submitted.\nWhere documentary evidence in a foreign language is submitted, it must be accompanied by a Chinese translation."
        },
        "noLabel": {
          "en": "Article 73."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 74,
        "text": {
          "en": "The people's court shall distinguish the true from the false in respect of audio-visual materials and, in combination with the other evidence in the case, examine and determine whether they can serve as the basis for ascertaining the facts."
        },
        "noLabel": {
          "en": "Article 74."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 75,
        "text": {
          "en": "All units and individuals that know the circumstances of a case shall have the duty to appear in court to testify. The persons in charge of the relevant units shall support witnesses in giving testimony.\nA person who is unable to express himself correctly shall not be a witness."
        },
        "noLabel": {
          "en": "Article 75."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 76,
        "text": {
          "en": "A witness shall appear in court to testify upon notification by a people's court. Where any of the following circumstances applies, the witness may, with the permission of the people's court, testify by such means as written testimony, audio-visual transmission technology or audio-visual materials:\n(a) the witness is unable to appear in court for health reasons;\n(b) the witness is unable to appear in court because of the distance of the journey and inconvenient transport;\n(c) the witness is unable to appear in court because of force majeure such as a natural disaster; or\n(d) the witness is unable to appear in court for any other justified reason."
        },
        "noLabel": {
          "en": "Article 76."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 77,
        "text": {
          "en": "The necessary expenses incurred by a witness in performing the duty to appear in court to testify, such as expenses for transport, accommodation and meals, and the loss of earnings, shall be borne by the losing party. Where a party applies for a witness to testify, the expenses shall be paid in advance by that party; where the party has not applied but the people's court notifies the witness to testify, the expenses shall be paid in advance by the people's court."
        },
        "noLabel": {
          "en": "Article 77."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 78,
        "text": {
          "en": "In respect of the statements of a party, the people's court shall, in combination with the other evidence in the case, examine and determine whether they can serve as the basis for ascertaining the facts.\nWhere a party refuses to make a statement, it shall not affect the people's court in ascertaining the facts of the case on the basis of the evidence."
        },
        "noLabel": {
          "en": "Article 78."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 79,
        "text": {
          "en": "A party may apply to a people's court for expert evaluation on a specialised issue in the ascertainment of facts. Where a party applies for expert evaluation, the qualified appraiser shall be determined by the parties through consultation; where consultation fails, the appraiser shall be designated by the people's court.\nWhere the party has not applied for expert evaluation but the people's court considers it necessary to have expert evaluation conducted on a specialised issue, it shall entrust a qualified appraiser to conduct the expert evaluation."
        },
        "noLabel": {
          "en": "Article 79."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 80,
        "text": {
          "en": "An appraiser shall have the right to review the materials of the case necessary for conducting the expert evaluation and may, when necessary, question the parties and witnesses.\nAn appraiser shall present a written expert opinion and sign or seal it."
        },
        "noLabel": {
          "en": "Article 80."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 81,
        "text": {
          "en": "Where a party raises an objection to the expert opinion or the people's court considers it necessary for the appraiser to appear in court, the appraiser shall appear in court to testify. Where, after being notified by the people's court, the appraiser refuses to appear in court to testify, the expert opinion shall not serve as the basis for ascertaining the facts, and the party that has paid the expenses for expert evaluation may demand the refund of the said expenses."
        },
        "noLabel": {
          "en": "Article 81."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 82,
        "text": {
          "en": "A party may apply to a people's court to notify a person with expertise to appear in court and put forward an opinion on the expert opinion made by the appraiser or on the professional issues."
        },
        "noLabel": {
          "en": "Article 82."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 83,
        "text": {
          "en": "For an inquest of physical evidence or of a site, the inspector must produce the certificate issued by the people's court, and the local grassroots organisation or the unit to which the party belongs shall be invited to send persons to participate. The party or an adult family member of the party shall be present; where they refuse to be present, it shall not affect the conduct of the inquest.\nThe relevant units and individuals shall, upon notification by the people's court, have the duty to protect the site and assist in the inquest work.\nThe inspector shall make a record of the circumstances and results of the inquest, which shall be signed or sealed by the inspector, the party and the invited participants."
        },
        "noLabel": {
          "en": "Article 83."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 84,
        "text": {
          "en": "Where evidence may be lost or destroyed or is difficult to obtain later, a party may, in the course of an action, apply to a people's court for the preservation of evidence, and the people's court may also take preservation measures on its own initiative.\nWhere the circumstances are urgent and evidence may be lost or destroyed or is difficult to obtain later, an interested party may, before filing a lawsuit or applying for arbitration, apply for the preservation of evidence to the people's court at the place where the evidence is located, at the place of the domicile of the respondent, or that has jurisdiction over the case.\nAs regards the other procedures for the preservation of evidence, the relevant provisions of Chapter IX of this Law on preservation shall apply by reference."
        },
        "noLabel": {
          "en": "Article 84."
        },
        "chapter": {
          "en": "Chapter VI Evidence"
        }
      },
      {
        "no": 85,
        "text": {
          "en": "Time periods include statutory time periods and time periods designated by the people's court.\nTime periods shall be calculated in hours, days, months and years. The hour and day on which a time period begins shall not be counted within the time period.\nWhere the last day of a time period falls on a statutory holiday, the first day after the statutory holiday shall be taken as the expiry date of the time period.\nA time period does not include time in transit; where a litigation document is posted before the expiry of the time period, it shall not be deemed to be overdue."
        },
        "noLabel": {
          "en": "Article 85."
        },
        "chapter": {
          "en": "Section 1 Time Periods"
        }
      },
      {
        "no": 86,
        "text": {
          "en": "Where a party has missed a time period because of an irresistible cause or any other justified reason, it may, within ten days after the removal of the obstacle, apply for the extension of the time period; whether the application is to be granted shall be decided by the people's court."
        },
        "noLabel": {
          "en": "Article 86."
        },
        "chapter": {
          "en": "Section 1 Time Periods"
        }
      },
      {
        "no": 87,
        "text": {
          "en": "The service of litigation documents must be accompanied by a certificate of service, on which the person on whom the document is to be served shall note the date of receipt and sign or seal it.\nThe date on which the person on whom the document is to be served signs for receipt on the certificate of service shall be the date of service."
        },
        "noLabel": {
          "en": "Article 87."
        },
        "chapter": {
          "en": "Section 2 Service"
        }
      },
      {
        "no": 88,
        "text": {
          "en": "Litigation documents shall be served directly on the persons on whom they are to be served. Where the person on whom a document is to be served is a citizen and the citizen himself is absent, the document may be signed for on his behalf by an adult family member living with him; where the person on whom a document is to be served is a legal person or any other organisation, the document shall be signed for by the legal representative of the legal person, the principal person in charge of the other organisation, or the person of the said legal person or organisation who is responsible for receiving documents; where the person on whom a document is to be served has an agent ad litem, the document may be delivered to his agent for signature on his behalf; and where the person on whom a document is to be served has designated a recipient to the people's court, the document shall be delivered to the designated recipient for signature.\nWhere an adult family member living with the person on whom a document is to be served, the person responsible for receiving documents of a legal person or any other organisation, an agent ad litem or a designated recipient signs for receipt on the certificate of service, the date of signature shall be the date of service."
        },
        "noLabel": {
          "en": "Article 88."
        },
        "chapter": {
          "en": "Section 2 Service"
        }
      },
      {
        "no": 89,
        "text": {
          "en": "Where the person on whom a litigation document is to be served or an adult family member living with him refuses to accept the document, the server may invite a representative of the relevant grassroots organisation or of the unit where he works to be present, explain the circumstances, note on the certificate of service the cause of the refusal and the date, have the certificate signed or sealed by the server and the witnesses, and leave the litigation document at the dwelling of the person on whom it is to be served; the server may also leave the litigation document at the dwelling of the person on whom it is to be served and record the process of service by such means as photographing or video recording, in which case the document shall be deemed to have been served."
        },
        "noLabel": {
          "en": "Article 89."
        },
        "chapter": {
          "en": "Section 2 Service"
        }
      },
      {
        "no": 90,
        "text": {
          "en": "Where the person on whom a litigation document is to be served consents, the people's court may serve the litigation document by electronic means capable of confirming his receipt thereof. Where a written judgment, a written order or a written mediation agreement is served by electronic means and the person on whom the document is to be served requests paper documents, the people's court shall provide paper documents.\nWhere service is made by the means prescribed in the preceding paragraph, the date on which the service information reaches the specific system of the person on whom the document is to be served shall be the date of service."
        },
        "noLabel": {
          "en": "Article 90."
        },
        "chapter": {
          "en": "Section 2 Service"
        }
      },
      {
        "no": 91,
        "text": {
          "en": "Where direct service of litigation documents is difficult, another people's court may be entrusted to serve the documents on its behalf, or the documents may be served by post. Where documents are served by post, the date of receipt noted on the receipt shall be the date of service."
        },
        "noLabel": {
          "en": "Article 91."
        },
        "chapter": {
          "en": "Section 2 Service"
        }
      },
      {
        "no": 92,
        "text": {
          "en": "Where the person on whom a document is to be served is a serviceman, the document shall be transferred through the political organ of the unit at or above the regiment level of the troops to which he belongs."
        },
        "noLabel": {
          "en": "Article 92."
        },
        "chapter": {
          "en": "Section 2 Service"
        }
      },
      {
        "no": 93,
        "text": {
          "en": "Where the person on whom a document is to be served is imprisoned, the document shall be transferred through the prison or detention house where he is held.\nWhere the person on whom a document is to be served is subjected to compulsory education measures, the document shall be transferred through the compulsory education institution where he is held."
        },
        "noLabel": {
          "en": "Article 93."
        },
        "chapter": {
          "en": "Section 2 Service"
        }
      },
      {
        "no": 94,
        "text": {
          "en": "After receiving the litigation documents, an organ or unit that serves the documents by transfer must immediately hand them to the person on whom they are to be served for him to sign for receipt, and the date of his signature for receipt on the certificate of service shall be the date of service."
        },
        "noLabel": {
          "en": "Article 94."
        },
        "chapter": {
          "en": "Section 2 Service"
        }
      },
      {
        "no": 95,
        "text": {
          "en": "Where the person on whom a document is to be served is missing, or the document cannot be served by any other means prescribed in this Section, service shall be effected by public notice. Where 30 days have elapsed from the day on which the public notice is issued, the document shall be deemed served.\nWhere service is effected by public notice, the reasons for and the course of the service shall be recorded in the case file."
        },
        "noLabel": {
          "en": "Article 95."
        },
        "chapter": {
          "en": "Section 2 Service"
        }
      },
      {
        "no": 96,
        "text": {
          "en": "In trying a civil case, a people's court shall conduct mediation on the basis of the voluntary participation of the parties and the clear ascertainment of the facts, distinguishing right from wrong."
        },
        "noLabel": {
          "en": "Article 96."
        },
        "chapter": {
          "en": "Chapter VIII Mediation"
        }
      },
      {
        "no": 97,
        "text": {
          "en": "In conducting mediation, a people's court may have a single judge or a collegial panel preside over the mediation, and shall, so far as possible, conduct mediation on the spot.\nIn conducting mediation, a people's court may notify the parties and witnesses to appear in court in a simple manner."
        },
        "noLabel": {
          "en": "Article 97."
        },
        "chapter": {
          "en": "Chapter VIII Mediation"
        }
      },
      {
        "no": 98,
        "text": {
          "en": "In conducting mediation, a people's court may invite relevant units or individuals to assist. The units and individuals invited shall assist the people's court in conducting mediation."
        },
        "noLabel": {
          "en": "Article 98."
        },
        "chapter": {
          "en": "Chapter VIII Mediation"
        }
      },
      {
        "no": 99,
        "text": {
          "en": "Where mediation leads to an agreement, both parties must do so voluntarily, and mediation shall not be imposed. The contents of a mediation agreement shall not violate the provisions of law."
        },
        "noLabel": {
          "en": "Article 99."
        },
        "chapter": {
          "en": "Chapter VIII Mediation"
        }
      },
      {
        "no": 100,
        "text": {
          "en": "Where mediation leads to an agreement, the people's court shall prepare a written mediation agreement. A written mediation agreement shall state the claims, the facts of the case and the result of the mediation.\nA written mediation agreement shall be signed by the judges and the court clerk, affixed with the seal of the people's court, and served on both parties.\nA written mediation agreement shall have legal effect after being signed for receipt by both parties."
        },
        "noLabel": {
          "en": "Article 100."
        },
        "chapter": {
          "en": "Chapter VIII Mediation"
        }
      },
      {
        "no": 101,
        "text": {
          "en": "For the following cases in which mediation leads to an agreement, a people's court need not prepare a written mediation agreement:\n(a) divorce cases in which the parties have become reconciled through mediation;\n(b) cases in which the adoption relationship is maintained through mediation;\n(c) cases that can be performed immediately; and\n(d) other cases for which a written mediation agreement need not be prepared.\nAn agreement for which a written mediation agreement need not be prepared shall be recorded in the record and shall have legal effect after being signed or sealed by both parties, the judges and the court clerk."
        },
        "noLabel": {
          "en": "Article 101."
        },
        "chapter": {
          "en": "Chapter VIII Mediation"
        }
      },
      {
        "no": 102,
        "text": {
          "en": "Where mediation fails to lead to an agreement or either party goes back on its word before the written mediation agreement is served, the people's court shall render a judgment in good time."
        },
        "noLabel": {
          "en": "Article 102."
        },
        "chapter": {
          "en": "Chapter VIII Mediation"
        }
      },
      {
        "no": 103,
        "text": {
          "en": "For a case in which an act of one party or any other reason may make the judgment difficult to execute or cause other damage to a party, a people's court may, upon the application of the opposing party, order the preservation of the party's property, order it to perform certain acts or prohibit it from performing certain acts; where the party has not applied, the people's court may also order the adoption of preservation measures when necessary.\nIn adopting preservation measures, a people's court may order the applicant to provide security; where the applicant does not provide security, the application shall be rejected by order.\nAfter accepting an application, a people's court must, where the circumstances are urgent, make an order within 48 hours; where the order provides for the adoption of preservation measures, the execution of the measures shall begin immediately."
        },
        "noLabel": {
          "en": "Article 103."
        },
        "chapter": {
          "en": "Chapter IX Preservation and Advance Execution"
        }
      },
      {
        "no": 104,
        "text": {
          "en": "Where an interested party, because of urgent circumstances, may suffer irreparable harm to its lawful rights and interests if it does not immediately apply for preservation, it may, before filing a lawsuit or applying for arbitration, apply to the people's court at the place where the property to be preserved is located, at the place of the respondent's domicile or at the place having jurisdiction over the case, for the adoption of preservation measures. The applicant shall provide security; where the applicant does not provide security, the application shall be rejected by order.\nAfter accepting an application, a people's court must make an order within 48 hours; where the order provides for the adoption of preservation measures, the execution of the measures shall begin immediately.\nWhere an applicant fails to file a lawsuit or apply for arbitration in accordance with the law within 30 days after the people's court adopts preservation measures, the people's court shall lift the preservation."
        },
        "noLabel": {
          "en": "Article 104."
        },
        "chapter": {
          "en": "Chapter IX Preservation and Advance Execution"
        }
      },
      {
        "no": 105,
        "text": {
          "en": "Preservation shall be limited to the property within the scope of the claims or related to the case."
        },
        "noLabel": {
          "en": "Article 105."
        },
        "chapter": {
          "en": "Chapter IX Preservation and Advance Execution"
        }
      },
      {
        "no": 106,
        "text": {
          "en": "Property preservation shall be effected by sealing up, seizing or freezing the property or by any other means prescribed by law. After preserving property, a people's court shall immediately notify the person whose property is preserved.\nProperty that has already been sealed up or frozen shall not be sealed up or frozen again."
        },
        "noLabel": {
          "en": "Article 106."
        },
        "chapter": {
          "en": "Chapter IX Preservation and Advance Execution"
        }
      },
      {
        "no": 107,
        "text": {
          "en": "Where the respondent provides security in a case of a property dispute, the people's court shall order the lifting of the preservation."
        },
        "noLabel": {
          "en": "Article 107."
        },
        "chapter": {
          "en": "Chapter IX Preservation and Advance Execution"
        }
      },
      {
        "no": 108,
        "text": {
          "en": "Where an application is erroneous, the applicant shall compensate the respondent for the losses suffered as a result of the preservation."
        },
        "noLabel": {
          "en": "Article 108."
        },
        "chapter": {
          "en": "Chapter IX Preservation and Advance Execution"
        }
      },
      {
        "no": 109,
        "text": {
          "en": "For the following cases, a people's court may, upon the application of a party, order advance execution:\n(a) cases in which payment is claimed of the expenses for the maintenance of elders, of the expenses for mutual support between spouses, of the expenses for the maintenance of children, of pension payments or of medical expenses;\n(b) cases in which payment of remuneration for labour is claimed; and\n(c) cases in which advance execution is necessary because of urgent circumstances."
        },
        "noLabel": {
          "en": "Article 109."
        },
        "chapter": {
          "en": "Chapter IX Preservation and Advance Execution"
        }
      },
      {
        "no": 110,
        "text": {
          "en": "Where a people's court orders advance execution, the following conditions shall be met:\n(a) the relationship of rights and obligations between the parties is definite, and failure to make advance execution will seriously affect the livelihood or the production and operation of the applicant; and\n(b) the respondent has the capacity to perform.\nA people's court may order the applicant to provide security; where the applicant does not provide security, the application shall be rejected. Where the applicant loses the action, it shall compensate the respondent for the property losses suffered as a result of the advance execution."
        },
        "noLabel": {
          "en": "Article 110."
        },
        "chapter": {
          "en": "Chapter IX Preservation and Advance Execution"
        }
      },
      {
        "no": 111,
        "text": {
          "en": "Where a party refuses to accept an order on preservation or advance execution, it may apply for reconsideration once. During the period of reconsideration, the execution of the order shall not be stopped."
        },
        "noLabel": {
          "en": "Article 111."
        },
        "chapter": {
          "en": "Chapter IX Preservation and Advance Execution"
        }
      },
      {
        "no": 112,
        "text": {
          "en": "Where a defendant who must appear in court refuses to appear in court without justified reasons after being summoned twice by subpoena, the people's court may issue a compulsory summons against him."
        },
        "noLabel": {
          "en": "Article 112."
        },
        "chapter": {
          "en": "Chapter X Compulsory Measures Against Obstruction of Civil Proceedings"
        }
      },
      {
        "no": 113,
        "text": {
          "en": "Participants in proceedings and other persons shall comply with the court rules.\nWhere a person violates the court rules, a people's court may reprimand him, order him to leave the court, or impose a fine or detention on him.\nWhere a person creates a disturbance in or rushes the court, insults, slanders, threatens or beats judges, or seriously disturbs the order of the court, criminal responsibility shall be investigated in accordance with the law; where the circumstances are relatively minor, a fine or detention shall be imposed on him."
        },
        "noLabel": {
          "en": "Article 113."
        },
        "chapter": {
          "en": "Chapter X Compulsory Measures Against Obstruction of Civil Proceedings"
        }
      },
      {
        "no": 114,
        "text": {
          "en": "Where a participant in proceedings or any other person commits any of the following acts, a people's court may, according to the seriousness of the circumstances, impose a fine or detention; where a crime is constituted, criminal responsibility shall be investigated in accordance with the law:\n(a) forging or destroying important evidence, thereby obstructing the trial of the case by the people's court;\n(b) preventing a witness from giving testimony or instigating, bribing or coercing another person to give false testimony by means of violence, threats or bribery;\n(c) concealing, transferring, selling off or damaging property that has already been sealed up or seized, or property that has already been inventoried and ordered to be kept in its custody, or transferring property that has already been frozen;\n(d) insulting, slandering, falsely accusing, beating or retaliating against judicial personnel, participants in proceedings, witnesses, translators, appraisers, inspectors or persons assisting in execution;\n(e) obstructing judicial personnel in the performance of their duties by means of violence, threats or any other means; or\n(f) refusing to perform a judgment or order of a people's court that has already become legally effective.\nWhere a unit commits any of the acts prescribed in the preceding paragraph, a people's court may impose a fine or detention on its principal person in charge or persons directly responsible; where a crime is constituted, criminal responsibility shall be investigated in accordance with the law."
        },
        "noLabel": {
          "en": "Article 114."
        },
        "chapter": {
          "en": "Chapter X Compulsory Measures Against Obstruction of Civil Proceedings"
        }
      },
      {
        "no": 115,
        "text": {
          "en": "Where the parties maliciously collude with each other in an attempt to infringe State interests, the public interests of the society or the lawful rights and interests of another person by means of litigation or mediation, the people's court shall reject their claims and may, according to the seriousness of the circumstances, impose a fine or detention; where a crime is constituted, criminal responsibility shall be investigated in accordance with the law.\nWhere a party unilaterally fabricates the basic facts of a civil case and files a lawsuit in a people's court in an attempt to infringe State interests, the public interests of the society or the lawful rights and interests of another person, the provisions of the preceding paragraph shall apply."
        },
        "noLabel": {
          "en": "Article 115."
        },
        "chapter": {
          "en": "Chapter X Compulsory Measures Against Obstruction of Civil Proceedings"
        }
      },
      {
        "no": 116,
        "text": {
          "en": "Where the person subject to execution maliciously colludes with another person in an attempt to evade the performance of the obligations determined in a legal document by means of litigation, arbitration or mediation, the people's court may, according to the seriousness of the circumstances, impose a fine or detention; where a crime is constituted, criminal responsibility shall be investigated in accordance with the law."
        },
        "noLabel": {
          "en": "Article 116."
        },
        "chapter": {
          "en": "Chapter X Compulsory Measures Against Obstruction of Civil Proceedings"
        }
      },
      {
        "no": 117,
        "text": {
          "en": "Where a unit obliged to assist in investigation or execution commits any of the following acts, the people's court may, in addition to ordering it to perform its obligation of assistance, impose a fine on it:\n(a) a relevant unit refuses or obstructs the investigation and collection of evidence by a people's court;\n(b) after receiving a notice of a people's court for assistance in execution, a relevant unit refuses to assist in the inquiry, seizure, freezing, transfer or conversion of property into money;\n(c) after receiving a notice of a people's court for assistance in execution, a relevant unit refuses to assist in withholding the income of the person subject to execution, handling the transfer procedures for the certificates of property rights, or transferring relevant bills, certificates or other property; or\n(d) the unit refuses to assist in execution in any other manner.\nWhere a unit commits any of the acts prescribed in the preceding paragraph, a people's court may impose a fine on its principal person in charge or persons directly responsible; where the unit still fails to perform its obligation of assistance, detention may be imposed; and the people's court may put forward a judicial recommendation to a supervisory organ or a relevant organ for the imposition of a disciplinary sanction."
        },
        "noLabel": {
          "en": "Article 117."
        },
        "chapter": {
          "en": "Chapter X Compulsory Measures Against Obstruction of Civil Proceedings"
        }
      },
      {
        "no": 118,
        "text": {
          "en": "The amount of a fine imposed on an individual shall be not more than RMB 100,000. The amount of a fine imposed on a unit shall be not less than RMB 50,000 but not more than RMB 1,000,000.\nThe term of detention shall be not more than 15 days.\nA person detained shall be handed over by the people's court to the public security organ for custody. During the period of detention, where the person detained admits and corrects the error, the people's court may decide to terminate the detention in advance."
        },
        "noLabel": {
          "en": "Article 118."
        },
        "chapter": {
          "en": "Chapter X Compulsory Measures Against Obstruction of Civil Proceedings"
        }
      },
      {
        "no": 119,
        "text": {
          "en": "A compulsory summons, a fine or detention must be approved by the president of the court.\nA compulsory summons shall be effected by issuing a warrant of compulsory summons.\nA fine or detention shall be imposed by issuing a written decision. Where a person refuses to accept the decision, he may apply for reconsideration once to the people's court at the next higher level. During the period of reconsideration, the execution shall not be stopped."
        },
        "noLabel": {
          "en": "Article 119."
        },
        "chapter": {
          "en": "Chapter X Compulsory Measures Against Obstruction of Civil Proceedings"
        }
      },
      {
        "no": 120,
        "text": {
          "en": "Compulsory measures against obstruction of civil proceedings must be decided by a people's court. Where any unit or individual unlawfully detains another person or unlawfully seizes another person's property privately in order to demand payment of a debt, criminal responsibility shall be investigated in accordance with the law, or detention or a fine shall be imposed."
        },
        "noLabel": {
          "en": "Article 120."
        },
        "chapter": {
          "en": "Chapter X Compulsory Measures Against Obstruction of Civil Proceedings"
        }
      },
      {
        "no": 121,
        "text": {
          "en": "Parties conducting civil litigation shall pay the case acceptance fee in accordance with the provisions. In property cases, the parties shall, in addition to paying the case acceptance fee, pay other litigation costs in accordance with the provisions.\nWhere a party has genuine difficulty in paying the litigation costs, it may, in accordance with the provisions, apply to the people's court for the deferment, reduction or exemption of payment.\nThe measures for the collection of litigation costs shall be formulated separately."
        },
        "noLabel": {
          "en": "Article 121."
        },
        "chapter": {
          "en": "Chapter XI Litigation Costs"
        }
      },
      {
        "no": 122,
        "text": {
          "en": "To file a lawsuit, the following conditions must be met:\n(a) the plaintiff is a citizen, a legal person or another organisation that has a direct interest in the case;\n(b) there is a definite defendant;\n(c) there are specific claims and the facts and reasons on which they are based; and\n(d) the case falls within the scope of civil litigation accepted by the people's court and within the jurisdiction of the people's court before which the action is brought."
        },
        "noLabel": {
          "en": "Article 122."
        },
        "chapter": {
          "en": "Section 1 Instituting and Accepting an Action"
        }
      },
      {
        "no": 123,
        "text": {
          "en": "A person filing a lawsuit shall file a statement of claim with the people's court and submit copies according to the number of defendants.\nWhere it is genuinely difficult to write a statement of claim, the action may be brought orally; the people's court shall record it in the record and notify the opposing party."
        },
        "noLabel": {
          "en": "Article 123."
        },
        "chapter": {
          "en": "Section 1 Instituting and Accepting an Action"
        }
      },
      {
        "no": 124,
        "text": {
          "en": "A statement of claim shall state the following particulars:\n(a) the name, sex, age, ethnicity, occupation, work unit, domicile and contact details of the plaintiff and, where the plaintiff is a legal person or another organisation, its name, domicile and the name, position and contact details of its legal representative or principal person in charge;\n(b) the name, sex, work unit, domicile and other information of the defendant and, where the defendant is a legal person or another organisation, its name, domicile and other information;\n(c) the claims and the facts and reasons on which they are based; and\n(d) the evidence and the sources of the evidence, and the names and domiciles of witnesses."
        },
        "noLabel": {
          "en": "Article 124."
        },
        "chapter": {
          "en": "Section 1 Instituting and Accepting an Action"
        }
      },
      {
        "no": 125,
        "text": {
          "en": "Where a civil dispute brought by the parties to the people's court is suitable for mediation, the people's court shall conduct mediation in advance, except where the parties refuse mediation."
        },
        "noLabel": {
          "en": "Article 125."
        },
        "chapter": {
          "en": "Section 1 Instituting and Accepting an Action"
        }
      },
      {
        "no": 126,
        "text": {
          "en": "A people's court shall safeguard the right of action of the parties as provided by law. Where an action meets the provisions of Article 122 of this Law, the people's court must accept it. Where the conditions for filing a lawsuit are met, the case shall be placed on file within seven days and the parties shall be notified; where the conditions for filing a lawsuit are not met, the people's court shall issue a written order not to accept the case within seven days; where the plaintiff refuses to accept the order, he may file an appeal."
        },
        "noLabel": {
          "en": "Article 126."
        },
        "chapter": {
          "en": "Section 1 Instituting and Accepting an Action"
        }
      },
      {
        "no": 127,
        "text": {
          "en": "A people's court shall deal with the following actions in light of the circumstances:\n(a) where, under the Administrative Procedure Law, the matter falls within the scope of administrative litigation, the plaintiff shall be notified to bring an administrative action;\n(b) where, as provided by law, the parties have concluded a written arbitration agreement to apply for arbitration and the action shall not be brought in a people's court, the plaintiff shall be notified to apply for arbitration to an arbitration institution;\n(c) where, as provided by law, the dispute should be handled by another organ, the plaintiff shall be notified to apply to the relevant organ for settlement;\n(d) where the case does not fall within the jurisdiction of this people's court, the plaintiff shall be notified to file the lawsuit in the people's court that has jurisdiction;\n(e) where a party files a lawsuit again in a case in which a judgment, order or written mediation agreement has already become legally effective, the plaintiff shall be notified to apply for retrial, except where a people's court has issued an order permitting the withdrawal of the action;\n(f) where, as provided by law, an action shall not be brought within a specified period and the action is brought within that period, the action shall not be accepted; or\n(g) where, in a divorce case in which divorce was not granted by judgment and the parties became reconciled through mediation, or in a case in which the adoption relationship was maintained by judgment or through mediation, the plaintiff files a lawsuit again within six months without new circumstances or new reasons, the action shall not be accepted."
        },
        "noLabel": {
          "en": "Article 127."
        },
        "chapter": {
          "en": "Section 1 Instituting and Accepting an Action"
        }
      },
      {
        "no": 128,
        "text": {
          "en": "Within five days from the day on which the case is placed on file, a people's court shall serve a copy of the statement of claim on the defendant, and the defendant shall submit a statement of defence within 15 days from the day on which he receives it. A statement of defence shall state the name, sex, age, ethnicity, occupation, work unit, domicile and contact details of the defendant; where the defendant is a legal person or another organisation, it shall state its name, domicile and the name, position and contact details of its legal representative or principal person in charge. Within five days from the day on which the people's court receives the statement of defence, it shall serve a copy of the statement of defence on the plaintiff.\nWhere the defendant does not submit a statement of defence, the trial by the people's court shall not be affected."
        },
        "noLabel": {
          "en": "Article 128."
        },
        "chapter": {
          "en": "Section 2 Preparations for Trial"
        }
      },
      {
        "no": 129,
        "text": {
          "en": "For a case it has decided to accept, a people's court shall inform the parties of the relevant litigation rights and obligations in the notice of acceptance of the case and the notice of response to the action, or inform them orally."
        },
        "noLabel": {
          "en": "Article 129."
        },
        "chapter": {
          "en": "Section 2 Preparations for Trial"
        }
      },
      {
        "no": 130,
        "text": {
          "en": "After a people's court accepts a case, where a party has an objection to jurisdiction, it shall raise the objection within the period for submitting a statement of defence. The people's court shall examine the objection raised by the party; where the objection is upheld, it shall order the transfer of the case to the people's court that has jurisdiction; where the objection is not upheld, it shall issue an order rejecting the objection.\nWhere a party has not raised an objection to jurisdiction and has responded to the action and submitted a defence, or has filed a counterclaim, the people's court before which the action is brought shall be deemed to have jurisdiction, unless the provisions on hierarchical jurisdiction and exclusive jurisdiction are violated."
        },
        "noLabel": {
          "en": "Article 130."
        },
        "chapter": {
          "en": "Section 2 Preparations for Trial"
        }
      },
      {
        "no": 131,
        "text": {
          "en": "Once the judges have been determined, the parties shall be notified within three days."
        },
        "noLabel": {
          "en": "Article 131."
        },
        "chapter": {
          "en": "Section 2 Preparations for Trial"
        }
      },
      {
        "no": 132,
        "text": {
          "en": "Judges must carefully examine the litigation materials and investigate and collect the necessary evidence."
        },
        "noLabel": {
          "en": "Article 132."
        },
        "chapter": {
          "en": "Section 2 Preparations for Trial"
        }
      },
      {
        "no": 133,
        "text": {
          "en": "When a people's court dispatches personnel to conduct an investigation, the personnel shall show their credentials to the person under investigation.\nAfter the record of the investigation has been checked by the person under investigation, it shall be signed or sealed by the person under investigation and the investigator."
        },
        "noLabel": {
          "en": "Article 133."
        },
        "chapter": {
          "en": "Section 2 Preparations for Trial"
        }
      },
      {
        "no": 134,
        "text": {
          "en": "A people's court may, where necessary, entrust a people's court in another locality to conduct an investigation.\nWhere an investigation is entrusted, the items and requirements of the investigation must be clearly stated. The entrusted people's court may conduct a supplementary investigation on its own initiative.\nAfter receiving the letter of entrustment, the entrusted people's court shall complete the investigation within 30 days; where it is unable to complete the investigation for some reason, it shall notify the entrusting people's court by letter within the said period."
        },
        "noLabel": {
          "en": "Article 134."
        },
        "chapter": {
          "en": "Section 2 Preparations for Trial"
        }
      },
      {
        "no": 135,
        "text": {
          "en": "Where a party that must participate in the action jointly fails to participate in the action, the people's court shall notify the party to participate in the action."
        },
        "noLabel": {
          "en": "Article 135."
        },
        "chapter": {
          "en": "Section 2 Preparations for Trial"
        }
      },
      {
        "no": 136,
        "text": {
          "en": "A people's court shall deal with a case it has accepted in light of the circumstances:\n(a) where the parties have no dispute and the conditions prescribed for the procedure for supervision and urging are met, the case may be transferred to the procedure for supervision and urging;\n(b) where mediation may be conducted before the hearing in court, the dispute shall be settled promptly by way of mediation;\n(c) whether the summary procedure or the ordinary procedure is to be applied shall be determined in light of the circumstances of the case; and\n(d) where a trial in court is necessary, the points at issue shall be clarified by such means as requiring the parties to exchange evidence."
        },
        "noLabel": {
          "en": "Article 136."
        },
        "chapter": {
          "en": "Section 2 Preparations for Trial"
        }
      },
      {
        "no": 137,
        "text": {
          "en": "In trying civil cases, a people's court shall hear the cases in public, except where State secrets or personal privacy are involved or as otherwise provided by law.\nDivorce cases and cases involving trade secrets may not be heard in public where the parties so apply."
        },
        "noLabel": {
          "en": "Article 137."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 138,
        "text": {
          "en": "In trying civil cases, a people's court shall, where necessary, conduct circuit trials and handle cases on the spot."
        },
        "noLabel": {
          "en": "Article 138."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 139,
        "text": {
          "en": "In trying a civil case, a people's court shall notify the parties and other participants in proceedings three days before the hearing in court. Where a case is heard in public, public notice shall be given of the names of the parties, the cause of action and the time and place of the hearing in court."
        },
        "noLabel": {
          "en": "Article 139."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 140,
        "text": {
          "en": "Before the trial in court, the court clerk shall verify whether the parties and other participants in proceedings have appeared in court and announce the court rules.\nAt the trial in court, the presiding judge or the single judge shall check the identities of the parties, announce the cause of action, announce the list of judges, judge assistants and court clerks, inform the parties of the relevant litigation rights and obligations, and ask the parties whether they apply for the challenge."
        },
        "noLabel": {
          "en": "Article 140."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 141,
        "text": {
          "en": "Court investigation shall be conducted in the following order:\n(a) statements by the parties;\n(b) the witnesses shall be informed of their rights and obligations, the witnesses shall give testimony, and the testimony of witnesses who do not appear in court shall be read out;\n(c) documentary evidence, material evidence, audio-visual materials and electronic data shall be produced;\n(d) expert opinions shall be read out; and\n(e) the record of the inquest shall be read out."
        },
        "noLabel": {
          "en": "Article 141."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 142,
        "text": {
          "en": "The parties may present new evidence in court.\nWith the permission of the court, a party may put questions to witnesses, appraisers and inspectors.\nWhere a party requests a new investigation, expert evaluation or inquest, whether the request is granted shall be decided by the people's court."
        },
        "noLabel": {
          "en": "Article 142."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 143,
        "text": {
          "en": "Where the plaintiff increases his claims, the defendant files a counterclaim, or a third party presents claims related to the case, they may be tried in a joined trial."
        },
        "noLabel": {
          "en": "Article 143."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 144,
        "text": {
          "en": "Court debate shall be conducted in the following order:\n(a) the plaintiff and his agent ad litem shall state their case;\n(b) the defendant and his agent ad litem shall present a defence;\n(c) the third party and his agent ad litem shall state their case or present a defence; and\n(d) the parties shall debate with one another.\nAt the conclusion of the court debate, the presiding judge or the single judge shall solicit the final opinions of each side in the order of the plaintiff, the defendant and the third party."
        },
        "noLabel": {
          "en": "Article 144."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 145,
        "text": {
          "en": "At the conclusion of the court debate, a judgment shall be rendered in accordance with the law. Where mediation is possible before the judgment is rendered, mediation may still be conducted; where mediation fails to lead to an agreement, a judgment shall be rendered in good time."
        },
        "noLabel": {
          "en": "Article 145."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 146,
        "text": {
          "en": "Where the plaintiff, having been summoned by subpoena, refuses to appear in court without justified reasons, or withdraws from the court midway without the permission of the court, the action may be treated as withdrawn; where the defendant has filed a counterclaim, judgment may be rendered by default."
        },
        "noLabel": {
          "en": "Article 146."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 147,
        "text": {
          "en": "Where the defendant, having been summoned by subpoena, refuses to appear in court without justified reasons, or withdraws from the court midway without the permission of the court, judgment may be rendered by default."
        },
        "noLabel": {
          "en": "Article 147."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 148,
        "text": {
          "en": "Before the pronouncement of judgment, where the plaintiff applies to withdraw the action, whether the application is granted shall be decided by the people's court by order.\nWhere the people's court decides by order not to allow the withdrawal of the action and the plaintiff, having been summoned by subpoena, refuses to appear in court without justified reasons, judgment may be rendered by default."
        },
        "noLabel": {
          "en": "Article 148."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 149,
        "text": {
          "en": "The trial in court may be postponed under any of the following circumstances:\n(a) a party or another participant in proceedings who must appear in court fails to appear in court for justified reasons;\n(b) a party raises an application for challenge at short notice;\n(c) it is necessary to notify new witnesses to appear in court, obtain new evidence, conduct a new expert evaluation or inquest, or make a supplementary investigation; or\n(d) other circumstances under which the trial shall be postponed."
        },
        "noLabel": {
          "en": "Article 149."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 150,
        "text": {
          "en": "The court clerk shall record all the activities of the trial in court in the record, and the record shall be signed by the judges and the court clerk.\nThe record of the court session shall be read out in court; the parties and other participants in proceedings may also be informed that they may read it in court or within five days. Where a party or another participant in proceedings considers that there is an omission or error in the record of his statement, he shall have the right to apply for correction. Where no correction is made, the application shall be recorded in the case file.\nThe record of the court session shall be signed or sealed by the parties and other participants in proceedings. Where a person refuses to sign or seal it, the circumstances shall be noted and attached to the case file."
        },
        "noLabel": {
          "en": "Article 150."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 151,
        "text": {
          "en": "A people's court shall pronounce judgment in public in all cases, whether tried in public or not in public.\nWhen judgment is pronounced in court, the written judgment shall be sent within 10 days; where judgment is pronounced on a fixed date, the written judgment shall be issued immediately after the pronouncement.\nWhen pronouncing judgment, the court must inform the parties of the right of appeal, the time limit for appeal and the people's court with which the appeal may be filed.\nWhen pronouncing a judgment of divorce, the court must inform the parties that they shall not remarry before the judgment becomes legally effective."
        },
        "noLabel": {
          "en": "Article 151."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 152,
        "text": {
          "en": "A people's court shall conclude the trial within six months from the day on which the case is placed on file for a case to which the ordinary procedure is applied. Where, due to special circumstances, an extension of the time limit is necessary, the time limit may be extended by six months upon the approval of the president of the court; where a further extension is necessary, the matter shall be reported to the people's court at a higher level for approval."
        },
        "noLabel": {
          "en": "Article 152."
        },
        "chapter": {
          "en": "Section 3 Trial in Court"
        }
      },
      {
        "no": 153,
        "text": {
          "en": "The action shall be suspended under any of the following circumstances:\n(a) a party dies, and it is necessary to wait for the successor to state whether to participate in the action;\n(b) a party loses the capacity to conduct litigation and the statutory agent has not yet been determined;\n(c) the legal person or another organisation that is a party has terminated and a successor to its rights and obligations has not yet been determined;\n(d) a party is unable to participate in the action for an irresistible reason;\n(e) the trial of this case must be based on the outcome of the trial of another case, and the other case has not yet been concluded; or\n(f) any other circumstance under which the action shall be suspended.\nAfter the cause of the suspension of the action has been eliminated, the action shall be resumed."
        },
        "noLabel": {
          "en": "Article 153."
        },
        "chapter": {
          "en": "Section 4 Suspension and Termination of Litigation"
        }
      },
      {
        "no": 154,
        "text": {
          "en": "The action shall be terminated under any of the following circumstances:\n(a) the plaintiff dies leaving no successor, or the successor waives the right of action;\n(b) the defendant dies leaving no estate and no person who shall assume the obligation;\n(c) in a divorce case, a party dies; or\n(d) in a case in which payment is claimed of the expenses for the maintenance of elders, of the expenses for mutual support between spouses or of the expenses for the maintenance of children, or in a case for the termination of an adoption relationship, a party dies."
        },
        "noLabel": {
          "en": "Article 154."
        },
        "chapter": {
          "en": "Section 4 Suspension and Termination of Litigation"
        }
      },
      {
        "no": 155,
        "text": {
          "en": "A written judgment shall state the outcome of the judgment and the reasons for the judgment. A written judgment shall contain the following:\n(a) the cause of action, the claims, and the facts and reasons in dispute;\n(b) the facts and reasons found in the judgment and the law applied and the reasons therefor;\n(c) the outcome of the judgment and the bearing of litigation costs; and\n(d) the time limit for appeal and the people's court with which the appeal may be filed.\nA written judgment shall be signed by the judges and the court clerk and affixed with the seal of the people's court."
        },
        "noLabel": {
          "en": "Article 155."
        },
        "chapter": {
          "en": "Section 5 Judgment and Order"
        }
      },
      {
        "no": 156,
        "text": {
          "en": "Where, in trying a case, a people's court finds that part of the facts is already clear, it may render a judgment on that part in advance."
        },
        "noLabel": {
          "en": "Article 156."
        },
        "chapter": {
          "en": "Section 5 Judgment and Order"
        }
      },
      {
        "no": 157,
        "text": {
          "en": "Orders shall apply to the following:\n(a) not accepting a case;\n(b) an objection to jurisdiction;\n(c) rejecting an action;\n(d) preservation and advance execution;\n(e) permitting or not permitting the withdrawal of the action;\n(f) suspending or terminating the action;\n(g) correcting clerical errors in a written judgment;\n(h) suspending or terminating enforcement;\n(i) rescinding or refusing to enforce an arbitral award;\n(j) not enforcing an instrument of obligation to which a notary organ has given compulsory enforceability; or\n(k) other matters that require resolution by order.\nAn appeal may be filed against the orders under subparagraphs (a) to (c) of the preceding paragraph.\nA written order shall state the outcome of the order and the reasons for making the order. A written order shall be signed by the judges and the court clerk and affixed with the seal of the people's court. Where an order is made orally, it shall be recorded in the record."
        },
        "noLabel": {
          "en": "Article 157."
        },
        "chapter": {
          "en": "Section 5 Judgment and Order"
        }
      },
      {
        "no": 158,
        "text": {
          "en": "The judgments and orders of the Supreme People's Court, and the judgments and orders against which no appeal is allowed by law or against which no appeal has been filed upon expiry of the time limit for appeal, are judgments and orders that have become legally effective."
        },
        "noLabel": {
          "en": "Article 158."
        },
        "chapter": {
          "en": "Section 5 Judgment and Order"
        }
      },
      {
        "no": 159,
        "text": {
          "en": "The public may consult written judgments and written orders that have become legally effective, except for the contents involving State secrets, trade secrets or personal privacy."
        },
        "noLabel": {
          "en": "Article 159."
        },
        "chapter": {
          "en": "Section 5 Judgment and Order"
        }
      },
      {
        "no": 160,
        "text": {
          "en": "Where a primary people's court or a tribunal dispatched by it tries a simple civil case in which the facts are clear, the relationship of rights and obligations is definite and the dispute is not great, the provisions of this Chapter shall apply.\nWhere a primary people's court or a tribunal dispatched by it tries a civil case other than those prescribed in the preceding paragraph, the parties may also agree to apply the summary procedure."
        },
        "noLabel": {
          "en": "Article 160."
        },
        "chapter": {
          "en": "Chapter XIII Summary Procedure"
        }
      },
      {
        "no": 161,
        "text": {
          "en": "For a simple civil case, the plaintiff may bring the action orally.\nThe parties may both appear at the same time before a primary people's court or a tribunal dispatched by it to request resolution of the dispute. The primary people's court or the tribunal dispatched by it may try the case immediately or set another date for the trial."
        },
        "noLabel": {
          "en": "Article 161."
        },
        "chapter": {
          "en": "Chapter XIII Summary Procedure"
        }
      },
      {
        "no": 162,
        "text": {
          "en": "Where a primary people's court or a tribunal dispatched by it tries a simple civil case, it may, in a simple manner, summon the parties and witnesses, serve litigation documents and try the case, but shall safeguard the right of the parties to state their opinions."
        },
        "noLabel": {
          "en": "Article 162."
        },
        "chapter": {
          "en": "Chapter XIII Summary Procedure"
        }
      },
      {
        "no": 163,
        "text": {
          "en": "A simple civil case shall be tried by a single judge and shall not be subject to the restrictions prescribed in Articles 139, 141 and 144 of this Law."
        },
        "noLabel": {
          "en": "Article 163."
        },
        "chapter": {
          "en": "Chapter XIII Summary Procedure"
        }
      },
      {
        "no": 164,
        "text": {
          "en": "Where a people's court applies the summary procedure in trying a case, it shall conclude the trial within three months from the day on which the case is placed on file. Where, due to special circumstances, an extension of the time limit is necessary, the time limit may be extended by one month upon the approval of the president of the court."
        },
        "noLabel": {
          "en": "Article 164."
        },
        "chapter": {
          "en": "Chapter XIII Summary Procedure"
        }
      },
      {
        "no": 165,
        "text": {
          "en": "Where a primary people's court or a tribunal dispatched by it tries a simple civil case involving the payment of money in which the facts are clear, the relationship of rights and obligations is definite and the dispute is not great, and the amount of the subject matter is not more than 50% of the average annual wage of employees in the province, autonomous region or municipality directly under the Central Government for the preceding year, the case shall be tried under the small claims procedure and the judgment shall be final after the first instance.\nWhere a primary people's court or a tribunal dispatched by it tries a civil case prescribed in the preceding paragraph in which the amount of the subject matter exceeds 50% but is not more than twice the average annual wage of employees in the province, autonomous region or municipality directly under the Central Government for the preceding year, the parties may also agree to apply the small claims procedure."
        },
        "noLabel": {
          "en": "Article 165."
        },
        "chapter": {
          "en": "Chapter XIII Summary Procedure"
        }
      },
      {
        "no": 166,
        "text": {
          "en": "The small claims procedure shall not apply to the following civil cases tried by a people's court:\n(a) cases involving personal relationships or the confirmation of property rights;\n(b) cases involving foreign elements;\n(c) cases that require evaluation or expert evaluation, or cases in which an objection is raised to the results of pre-litigation evaluation or expert evaluation;\n(d) cases in which the whereabouts of a party is unknown;\n(e) cases in which a party files a counterclaim; or\n(f) other cases that are not suitable for trial under the small claims procedure."
        },
        "noLabel": {
          "en": "Article 166."
        },
        "chapter": {
          "en": "Chapter XIII Summary Procedure"
        }
      },
      {
        "no": 167,
        "text": {
          "en": "Where a people's court applies the small claims procedure in trying a case, it may conclude the trial in one court session and pronounce judgment in court."
        },
        "noLabel": {
          "en": "Article 167."
        },
        "chapter": {
          "en": "Chapter XIII Summary Procedure"
        }
      },
      {
        "no": 168,
        "text": {
          "en": "Where a people's court applies the small claims procedure in trying a case, it shall conclude the trial within two months from the day on which the case is placed on file. Where, due to special circumstances, an extension of the time limit is necessary, the time limit may be extended by one month upon the approval of the president of the court."
        },
        "noLabel": {
          "en": "Article 168."
        },
        "chapter": {
          "en": "Chapter XIII Summary Procedure"
        }
      },
      {
        "no": 169,
        "text": {
          "en": "Where, in the course of trial, a people's court finds that a case is not suitable for trial under the small claims procedure, the case shall be tried by applying the other provisions of the summary procedure or be converted to the ordinary procedure by order.\nWhere a party considers that the trial of a case under the small claims procedure violates the provisions of law, it may raise an objection with the people's court. The people's court shall examine the objection raised by the party; where the objection is upheld, the case shall be tried by applying the other provisions of the summary procedure or be converted to the ordinary procedure by order; where the objection is not upheld, it shall be rejected by order."
        },
        "noLabel": {
          "en": "Article 169."
        },
        "chapter": {
          "en": "Chapter XIII Summary Procedure"
        }
      },
      {
        "no": 170,
        "text": {
          "en": "Where, in the course of trial, a people's court finds that a case is not suitable for the summary procedure, it shall convert the case to the ordinary procedure by order."
        },
        "noLabel": {
          "en": "Article 170."
        },
        "chapter": {
          "en": "Chapter XIII Summary Procedure"
        }
      },
      {
        "no": 171,
        "text": {
          "en": "Where a party refuses to accept the judgment of first instance of a local people's court, it shall have the right to file an appeal with the people's court at the next higher level within 15 days from the day on which the written judgment is served.\nWhere a party refuses to accept the order of first instance of a local people's court, it shall have the right to file an appeal with the people's court at the next higher level within 10 days from the day on which the written order is served."
        },
        "noLabel": {
          "en": "Article 171."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 172,
        "text": {
          "en": "An appeal shall be filed by submitting a written appeal. A written appeal shall state the names of the parties, the name of a legal person and the name of its legal representative or the name of another organisation and the name of its principal person in charge; the name of the people's court that originally tried the case, the number of the case and the cause of action; and the claims and reasons of the appeal."
        },
        "noLabel": {
          "en": "Article 172."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 173,
        "text": {
          "en": "A written appeal shall be filed through the people's court that originally tried the case, and copies shall be submitted according to the number of opposing parties or representatives.\nWhere a party files an appeal directly with the people's court of second instance, the people's court of second instance shall transfer the written appeal to the people's court that originally tried the case within five days."
        },
        "noLabel": {
          "en": "Article 173."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 174,
        "text": {
          "en": "Within five days from the day on which the people's court that originally tried the case receives a written appeal, it shall serve a copy of the written appeal on the opposing party, and the opposing party shall submit a statement of defence within 15 days from the day on which it receives it. The people's court shall serve a copy on the appellant within five days from the day on which it receives the statement of defence. Where the opposing party does not submit a statement of defence, the trial by the people's court shall not be affected.\nWithin five days from the day on which the people's court that originally tried the case receives the written appeal and the statement of defence, it shall report the case to the people's court of second instance together with the entire case file and the evidence."
        },
        "noLabel": {
          "en": "Article 174."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 175,
        "text": {
          "en": "The people's court of second instance shall examine the facts relevant to the claims of the appeal and the application of law."
        },
        "noLabel": {
          "en": "Article 175."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 176,
        "text": {
          "en": "The people's court of second instance shall try a case of appeal in court. Where, after reviewing the case file, conducting investigations and questioning the parties, no new facts, evidence or reasons have been presented and the people's court considers that a trial in court is not necessary, it may decide not to try the case in court.\nIn trying a case of appeal, the people's court of second instance may conduct the trial at its own court or at the place where the case occurred or at the place where the people's court that originally tried the case is located."
        },
        "noLabel": {
          "en": "Article 176."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 177,
        "text": {
          "en": "In trying a case of appeal, the people's court of second instance shall, after hearing the case, deal with it separately in accordance with the following circumstances:\n(a) where the facts found in the original judgment or order are clear and the law is correctly applied, the appeal shall be rejected and the original judgment or order shall be upheld by judgment or order;\n(b) where the facts found in the original judgment or order are erroneous or the law is erroneously applied, the judgment or order shall be altered, rescinded or modified by judgment or order in accordance with the law;\n(c) where the basic facts found in the original judgment are unclear, the original judgment shall be rescinded by order and the case remanded to the people's court that originally tried the case for retrial, or the judgment may be altered after the facts have been ascertained; or\n(d) where the original judgment omits a party or judgment is rendered by default in violation of the law, or the procedure prescribed by law is otherwise seriously violated, the original judgment shall be rescinded by order and the case remanded to the people's court that originally tried the case for retrial.\nWhere, after the people's court that originally tried the case has rendered a judgment on a case remanded for retrial, a party files an appeal, the people's court of second instance shall not remand the case for retrial again."
        },
        "noLabel": {
          "en": "Article 177."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 178,
        "text": {
          "en": "In dealing with a case of appeal against an order of a people's court of first instance, the people's court of second instance shall in all cases use an order."
        },
        "noLabel": {
          "en": "Article 178."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 179,
        "text": {
          "en": "In trying a case of appeal, the people's court of second instance may conduct mediation. Where mediation leads to an agreement, a written mediation agreement shall be prepared, which shall be signed by the judges and the court clerk and affixed with the seal of the people's court. After the written mediation agreement has been served, the judgment of the people's court that originally tried the case shall be deemed rescinded."
        },
        "noLabel": {
          "en": "Article 179."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 180,
        "text": {
          "en": "Before the pronouncement of judgment by the people's court of second instance, where the appellant applies to withdraw the appeal, whether the application is granted shall be decided by the people's court of second instance by order."
        },
        "noLabel": {
          "en": "Article 180."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 181,
        "text": {
          "en": "In hearing a case of appeal, the people's court of second instance shall apply the ordinary procedure of first instance, except as provided in this Chapter."
        },
        "noLabel": {
          "en": "Article 181."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 182,
        "text": {
          "en": "The judgments and orders of a people's court of second instance shall be final judgments and orders."
        },
        "noLabel": {
          "en": "Article 182."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 183,
        "text": {
          "en": "In hearing a case of appeal against a judgment, a people's court shall conclude the trial within three months from the day on which the case is placed on file at second instance. Where an extension is necessary because of special circumstances, it shall be subject to the approval of the president of the court.\nIn hearing a case of appeal against an order, a people's court shall make a final order within 30 days from the day on which the case is placed on file at second instance."
        },
        "noLabel": {
          "en": "Article 183."
        },
        "chapter": {
          "en": "Chapter XIV Procedure of Second Instance"
        }
      },
      {
        "no": 184,
        "text": {
          "en": "The provisions of this Chapter shall apply to the trial by people's courts of voter qualification cases, cases of the declaration of a person as missing or dead, cases for the designation of an administrator of an estate, cases for the determination of a citizen as a person without capacity for civil conduct or with limited capacity for civil conduct, cases for the determination of property as ownerless, cases for the confirmation of mediation agreements and cases for the realisation of security interests. Where no provisions are prescribed in this Chapter, the relevant provisions of this Law and of other laws shall apply."
        },
        "noLabel": {
          "en": "Article 184."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 185,
        "text": {
          "en": "Cases tried under the procedure prescribed in this Chapter shall be final after the first instance. Voter qualification cases and major or difficult cases shall be tried by a collegial panel composed of judges; other cases shall be tried by a single judge."
        },
        "noLabel": {
          "en": "Article 185."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 186,
        "text": {
          "en": "Where, in the course of trying a case under the procedure prescribed in this Chapter, a people's court finds that the case involves a dispute over civil rights and interests, it shall order the termination of the special procedure and notify the interested parties that they may file a separate lawsuit."
        },
        "noLabel": {
          "en": "Article 186."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 187,
        "text": {
          "en": "For a case tried under the special procedure, a people's court shall conclude the trial within 30 days from the day on which the case is placed on file or within 30 days after the expiry of the period of public notice. Where an extension is necessary because of special circumstances, it shall be subject to the approval of the president of the court, except in the trial of voter qualification cases."
        },
        "noLabel": {
          "en": "Article 187."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 188,
        "text": {
          "en": "Where a citizen refuses to accept a decision made by an election committee on his appeal against voter qualification, he may, five days before the day of election, file a lawsuit with the primary people's court at the place of the electoral district."
        },
        "noLabel": {
          "en": "Article 188."
        },
        "chapter": {
          "en": "Section 2 Cases Concerning the Qualification of Voters"
        }
      },
      {
        "no": 189,
        "text": {
          "en": "After accepting a voter qualification case, a people's court must conclude the trial before the day of election.\nIn the trial, the plaintiff, a representative of the election committee and the citizens concerned must participate.\nThe written judgment of the people's court shall, before the day of election, be served on the election committee and the plaintiff, and the citizens concerned shall be notified."
        },
        "noLabel": {
          "en": "Article 189."
        },
        "chapter": {
          "en": "Section 2 Cases Concerning the Qualification of Voters"
        }
      },
      {
        "no": 190,
        "text": {
          "en": "Where the whereabouts of a citizen have been unknown for two years and an interested party applies for the declaration of the citizen as missing, the application shall be filed with the primary people's court at the place of the domicile of the missing person.\nThe application shall state the facts and time of the disappearance of the missing person and the request, and shall be accompanied by a written certificate issued by a public security organ or any other relevant organ certifying that the whereabouts of the citizen are unknown."
        },
        "noLabel": {
          "en": "Article 190."
        },
        "chapter": {
          "en": "Section 3 Cases Concerning the Proclamation of a Person as Missing or Dead"
        }
      },
      {
        "no": 191,
        "text": {
          "en": "Where the whereabouts of a citizen have been unknown for four years, or the whereabouts of the citizen have been unknown for two years because of an accidental event, or the whereabouts of the citizen have been unknown because of an accidental event and a relevant organ has certified that the citizen cannot possibly survive, and an interested party applies for the declaration of the citizen as dead, the application shall be filed with the primary people's court at the place of the domicile of the person whose whereabouts are unknown.\nThe application shall state the facts and time of the disappearance and the request, and shall be accompanied by a written certificate issued by a public security organ or any other relevant organ certifying that the whereabouts of the citizen are unknown."
        },
        "noLabel": {
          "en": "Article 191."
        },
        "chapter": {
          "en": "Section 3 Cases Concerning the Proclamation of a Person as Missing or Dead"
        }
      },
      {
        "no": 192,
        "text": {
          "en": "After accepting a case of declaration of a person as missing or dead, a people's court shall issue a public notice in search of the missing person. The period of public notice for the declaration of a person as missing shall be three months, and the period of public notice for the declaration of a person as dead shall be one year. Where the whereabouts of a person are unknown because of an accidental event and a relevant organ has certified that the citizen cannot possibly survive, the period of public notice for the declaration of death shall be three months.\nUpon expiry of the period of public notice, the people's court shall, according to whether the fact of the declaration of the person as missing or dead has been confirmed, render a judgment declaring the person as missing or dead or a judgment rejecting the application."
        },
        "noLabel": {
          "en": "Article 192."
        },
        "chapter": {
          "en": "Section 3 Cases Concerning the Proclamation of a Person as Missing or Dead"
        }
      },
      {
        "no": 193,
        "text": {
          "en": "Where a citizen declared as missing or dead reappears, the people's court shall, upon the application of the person himself or an interested party, render a new judgment and rescind the original judgment."
        },
        "noLabel": {
          "en": "Article 193."
        },
        "chapter": {
          "en": "Section 3 Cases Concerning the Proclamation of a Person as Missing or Dead"
        }
      },
      {
        "no": 194,
        "text": {
          "en": "Where a dispute arises over the determination of an administrator of an estate and an interested party applies for the designation of an administrator of the estate, the application shall be filed with the primary people's court at the place of the domicile of the decedent at the time of death or at the place where the principal part of the estate is located.\nThe application shall state the time of death of the decedent, the grounds for the application and the specific request, and shall be accompanied by the relevant evidence of the death of the decedent."
        },
        "noLabel": {
          "en": "Article 194."
        },
        "chapter": {
          "en": "Section 4 Cases Concerning the Designation of Estate Administrators"
        }
      },
      {
        "no": 195,
        "text": {
          "en": "After accepting an application, a people's court shall examine and verify it and, under the principle of being conducive to the administration of the estate, render a judgment designating an administrator of the estate."
        },
        "noLabel": {
          "en": "Article 195."
        },
        "chapter": {
          "en": "Section 4 Cases Concerning the Designation of Estate Administrators"
        }
      },
      {
        "no": 196,
        "text": {
          "en": "Where the designated administrator of the estate dies or is terminated, loses capacity for civil conduct or is under any other circumstance making it impossible for him to continue performing the duties of estate administration, the people's court may, upon the application of an interested party or the administrator himself, designate another administrator of the estate."
        },
        "noLabel": {
          "en": "Article 196."
        },
        "chapter": {
          "en": "Section 4 Cases Concerning the Designation of Estate Administrators"
        }
      },
      {
        "no": 197,
        "text": {
          "en": "Where an administrator of an estate violates the duties of estate administration and seriously infringes the lawful rights and interests of a successor, a legatee or a creditor, the people's court may, upon the application of an interested party, revoke his qualification as an administrator of the estate and designate a new administrator of the estate in accordance with the law."
        },
        "noLabel": {
          "en": "Article 197."
        },
        "chapter": {
          "en": "Section 4 Cases Concerning the Designation of Estate Administrators"
        }
      },
      {
        "no": 198,
        "text": {
          "en": "An application for the determination of a citizen as a person without capacity for civil conduct or with limited capacity for civil conduct shall be filed by an interested party or a relevant organisation with the primary people's court at the place of the citizen's domicile.\nThe application shall state the facts and grounds for the citizen's incapacity for civil conduct or limited capacity for civil conduct."
        },
        "noLabel": {
          "en": "Article 198."
        },
        "chapter": {
          "en": "Section 5 Cases Concerning the Determination of Legal Incapacity or Restricted Legal Capacity of Citizens"
        }
      },
      {
        "no": 199,
        "text": {
          "en": "After accepting an application, a people's court shall, where necessary, conduct expert evaluation of the citizen sought to be determined as a person without capacity for civil conduct or with limited capacity for civil conduct. Where the applicant has provided an expert opinion, the people's court shall examine the expert opinion."
        },
        "noLabel": {
          "en": "Article 199."
        },
        "chapter": {
          "en": "Section 5 Cases Concerning the Determination of Legal Incapacity or Restricted Legal Capacity of Citizens"
        }
      },
      {
        "no": 200,
        "text": {
          "en": "In trying a case for the determination of a citizen as a person without capacity for civil conduct or with limited capacity for civil conduct, the people's court shall have a close relative of the citizen act as agent, except the applicant. Where the close relatives shift the responsibility onto each other, the people's court shall designate one of them to act as agent. Where the state of health of the citizen permits, the opinion of the person himself shall also be sought.\nWhere, after trial, the people's court finds that the application is supported by facts, it shall render a judgment determining that the citizen is a person without capacity for civil conduct or with limited capacity for civil conduct; where it finds that the application is not supported by facts, it shall render a judgment rejecting the application."
        },
        "noLabel": {
          "en": "Article 200."
        },
        "chapter": {
          "en": "Section 5 Cases Concerning the Determination of Legal Incapacity or Restricted Legal Capacity of Citizens"
        }
      },
      {
        "no": 201,
        "text": {
          "en": "Where, upon the application of the person determined as a person without capacity for civil conduct or with limited capacity for civil conduct, an interested party or a relevant organisation, it is confirmed that the cause of the citizen's incapacity for civil conduct or limited capacity for civil conduct has been eliminated, the people's court shall render a new judgment and rescind the original judgment."
        },
        "noLabel": {
          "en": "Article 201."
        },
        "chapter": {
          "en": "Section 5 Cases Concerning the Determination of Legal Incapacity or Restricted Legal Capacity of Citizens"
        }
      },
      {
        "no": 202,
        "text": {
          "en": "An application for the determination of property as ownerless shall be filed by a citizen, legal person or other organisation with the primary people's court at the place where the property is located. The application shall state the types and quantities of the property and the grounds for requesting the determination of the property as ownerless."
        },
        "noLabel": {
          "en": "Article 202."
        },
        "chapter": {
          "en": "Section 6 Cases Concerning the Determination of a Property as Ownerless"
        }
      },
      {
        "no": 203,
        "text": {
          "en": "After accepting an application and upon examination and verification, a people's court shall issue a public notice for the claiming of the property. Where no one claims the property upon expiry of one year from the issuance of the public notice, the people's court shall render a judgment determining the property as ownerless, and the property shall become the property of the State or the collective."
        },
        "noLabel": {
          "en": "Article 203."
        },
        "chapter": {
          "en": "Section 6 Cases Concerning the Determination of a Property as Ownerless"
        }
      },
      {
        "no": 204,
        "text": {
          "en": "Where, after a judgment determining property as ownerless is rendered, the original owner of the property or a successor appears and may, within the limitation period prescribed in the Civil Code, make a request for the property, the people's court shall, after examination and confirmation of the facts, render a new judgment and rescind the original judgment."
        },
        "noLabel": {
          "en": "Article 204."
        },
        "chapter": {
          "en": "Section 6 Cases Concerning the Determination of a Property as Ownerless"
        }
      },
      {
        "no": 205,
        "text": {
          "en": "Where a mediation agreement is reached through mediation conducted by a lawfully established mediation organisation and judicial confirmation is applied for, the application shall be jointly filed by both parties with the following people's courts within 30 days from the day on which the mediation agreement becomes effective:\n(a) where the mediation was conducted in advance upon the invitation of the people's court to the mediation organisation, the application shall be filed with the people's court that issued the invitation; and\n(b) where the mediation was conducted by the mediation organisation on its own initiative, the application shall be filed with the primary people's court at the place of the domicile of a party, at the place where the subject matter is located, or at the place where the mediation organisation is located; where the dispute involved in the mediation agreement should be under the jurisdiction of an intermediate people's court, the application shall be filed with the corresponding intermediate people's court."
        },
        "noLabel": {
          "en": "Article 205."
        },
        "chapter": {
          "en": "Section 7 Cases of Confirming Mediation Agreements"
        }
      },
      {
        "no": 206,
        "text": {
          "en": "After accepting an application and upon examination, where the mediation agreement conforms to the provisions of law, the people's court shall order that the mediation agreement is valid; where one party refuses to perform or fails to perform the agreement in full, the opposing party may apply to the people's court for enforcement; where the mediation agreement does not conform to the provisions of law, the people's court shall order the rejection of the application, and the parties may modify the original mediation agreement through mediation or reach a new mediation agreement, or may file a lawsuit in the people's court."
        },
        "noLabel": {
          "en": "Article 206."
        },
        "chapter": {
          "en": "Section 7 Cases of Confirming Mediation Agreements"
        }
      },
      {
        "no": 207,
        "text": {
          "en": "An application for the realisation of a security interest shall, in accordance with the Civil Code and other laws, be filed by the holder of the security interest or any other person entitled to request the realisation of the security interest with the primary people's court at the place where the secured property is located or where the security interest is registered."
        },
        "noLabel": {
          "en": "Article 207."
        },
        "chapter": {
          "en": "Section 8 Cases of Security Interest Realisation"
        }
      },
      {
        "no": 208,
        "text": {
          "en": "After accepting an application and upon examination, where the application conforms to the provisions of law, the people's court shall order the auction or sale of the secured property, and the parties may, on the basis of the order, apply to the people's court for enforcement; where the application does not conform to the provisions of law, the people's court shall order the rejection of the application, and the parties may file a lawsuit in the people's court."
        },
        "noLabel": {
          "en": "Article 208."
        },
        "chapter": {
          "en": "Section 8 Cases of Security Interest Realisation"
        }
      },
      {
        "no": 209,
        "text": {
          "en": "Where the president of a people's court at any level finds that a legally effective judgment, order or mediation agreement of his court is indeed erroneous and finds that a retrial is necessary, the matter shall be submitted to the adjudication committee for discussion and decision.\nWhere the Supreme People's Court finds that a legally effective judgment, order or mediation agreement of a local people's court at any level is erroneous, or where a people's court at a higher level finds that a legally effective judgment, order or mediation agreement of a people's court at a lower level is erroneous, it shall have the power to bring the case up for trial itself or to direct the people's court at a lower level to conduct a retrial."
        },
        "noLabel": {
          "en": "Article 209."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 210,
        "text": {
          "en": "Where a party considers that a legally effective judgment or order is erroneous, it may apply for retrial to the people's court at the next higher level; in a case in which one party consists of a large number of persons or both parties are citizens, the party may also apply for retrial to the people's court that originally tried the case. Where a party applies for retrial, the execution of the judgment or order shall not be stopped."
        },
        "noLabel": {
          "en": "Article 210."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 211,
        "text": {
          "en": "Where the application of a party falls under any of the following circumstances, the people's court shall order a retrial:\n(a) there is new evidence that is sufficient to overturn the original judgment or order;\n(b) the basic facts found in the original judgment or order are not supported by evidence;\n(c) the main evidence for the facts found in the original judgment or order is forged;\n(d) the main evidence for the facts found in the original judgment or order has not been cross-examined;\n(e) for the main evidence needed for the trial of the case, the party is unable to collect it on its own for objective reasons and has applied in writing to the people's court for investigation and collection, but the people's court has not investigated and collected the evidence;\n(f) the application of law in the original judgment or order is indeed erroneous;\n(g) the composition of the trial organisation is unlawful, or adjudicating personnel who shall be challenged in accordance with law have not been challenged;\n(h) a person without capacity to conduct litigation has conducted litigation without a statutory agent acting on his behalf, or a party who shall participate in the litigation has failed to participate in the litigation for a reason that is not attributable to the party itself or its agent ad litem;\n(i) the right of debate of a party is deprived in violation of the provisions of law;\n(j) judgment is rendered by default without the party having been summoned by subpoena;\n(k) the original judgment or order omits or exceeds the claims of the action;\n(l) the legal document on the basis of which the original judgment or order was made has been rescinded or modified; or\n(m) in trying the case, a member of the adjudicating personnel has committed embezzlement, accepted bribes, engaged in malpractices for personal gain or rendered a judgment in violation of the law."
        },
        "noLabel": {
          "en": "Article 211."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 212,
        "text": {
          "en": "Where a party adduces evidence to prove that the mediation leading to a mediation agreement that has become legally effective violated the principle of voluntariness, or that the content of the mediation agreement violates the law, the party may apply for retrial. Where, upon examination, the people's court finds the allegation to be true, it shall order a retrial."
        },
        "noLabel": {
          "en": "Article 212."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 213,
        "text": {
          "en": "A party shall not apply for retrial in respect of a legally effective judgment or mediation agreement terminating the marital relationship."
        },
        "noLabel": {
          "en": "Article 213."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 214,
        "text": {
          "en": "Where a party applies for retrial, it shall submit an application for retrial and other relevant materials. The people's court shall, within five days from the day on which it receives the application for retrial, send a copy of the application for retrial to the opposing party. The opposing party shall submit written opinions within 15 days from the day on which it receives the copy of the application for retrial; where the opposing party does not submit written opinions, the examination by the people's court shall not be affected. The people's court may require the applicant and the opposing party to supplement relevant materials and inquire about relevant matters."
        },
        "noLabel": {
          "en": "Article 214."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 215,
        "text": {
          "en": "A people's court shall conduct examination within three months from the day on which it receives the application for retrial; where the application conforms to the provisions of this Law, the court shall order a retrial; where the application does not conform to the provisions of this Law, the court shall reject the application by order. Where, due to special circumstances, an extension is necessary, the matter shall be subject to the approval of the president of the court.\nA case for which a retrial is ordered upon the application of a party shall be tried by a people's court at or above the intermediate level, except where the party has chosen, in accordance with Article 210 of this Law, to apply for retrial with a primary people's court. A case for which a retrial is ordered by the Supreme People's Court or a higher people's court may be retried by the court itself, assigned to another people's court for retrial, or assigned to the people's court that originally tried the case for retrial."
        },
        "noLabel": {
          "en": "Article 215."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 216,
        "text": {
          "en": "Where a party applies for retrial, the application shall be filed within six months after the judgment or order becomes legally effective; where any of the circumstances prescribed in subparagraphs (a), (c), (l) and (m) of Article 211 of this Law applies, the application shall be filed within six months from the day on which the party knows or should have known of the circumstance."
        },
        "noLabel": {
          "en": "Article 216."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 217,
        "text": {
          "en": "Where a retrial is decided for a case under the procedure for trial supervision, the enforcement of the original judgment, order or mediation agreement shall be stayed by order, except that in cases for the recovery of the expenses for the support of elders, of maintenance, of child support, of pension, of medical expenses or of labour remuneration, the enforcement need not be stayed."
        },
        "noLabel": {
          "en": "Article 217."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 218,
        "text": {
          "en": "Where a people's court retries a case under the procedure for trial supervision and the legally effective judgment or order was rendered by a people's court of first instance, the case shall be tried under the procedure of first instance, and a party may appeal against the judgment or order rendered in the retrial; where the legally effective judgment or order was rendered by a people's court of second instance, the case shall be tried under the procedure of second instance, and the judgment or order rendered in the retrial shall be legally effective; where a people's court at a higher level brings the case up for trial itself under the procedure for trial supervision, the case shall be tried under the procedure of second instance, and the judgment or order rendered in the retrial shall be legally effective.\nIn trying a case of retrial, a people's court shall form a new collegial panel."
        },
        "noLabel": {
          "en": "Article 218."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 219,
        "text": {
          "en": "Where the Supreme People's Procuratorate finds that a legally effective judgment or order of a people's court at any level falls under any of the circumstances prescribed in Article 211 of this Law, or finds that a mediation agreement harms the interests of the State or the public interest, it shall file a protest; where a people's procuratorate at a higher level finds that a legally effective judgment or order of a people's court at a lower level falls under any of the circumstances prescribed in Article 211 of this Law, or finds that a mediation agreement harms the interests of the State or the public interest, it shall file a protest.\nWhere a local people's procuratorate at any level finds that a legally effective judgment or order of the people's court at the same level falls under any of the circumstances prescribed in Article 211 of this Law, or finds that a mediation agreement harms the interests of the State or the public interest, it may file a procuratorial suggestion with the people's court at the same level and report the matter to the people's procuratorate at a higher level for the record; it may also request the people's procuratorate at a higher level to file a protest with the people's court at the same level.\nA people's procuratorate at any level shall have the power to file a procuratorial suggestion with the people's court at the same level in respect of unlawful acts of adjudicating personnel in trial procedures other than the procedure for trial supervision."
        },
        "noLabel": {
          "en": "Article 219."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 220,
        "text": {
          "en": "Under any of the following circumstances, a party may apply to a people's procuratorate for a procuratorial suggestion or a protest:\n(a) the people's court rejects the application for retrial;\n(b) the people's court fails to make an order on the application for retrial upon expiry of the time limit; or\n(c) the judgment or order rendered in the retrial is clearly erroneous.\nThe people's procuratorate shall examine the application of the party within three months and make a decision on whether to file a procuratorial suggestion or a protest. A party shall not again apply to a people's procuratorate for a procuratorial suggestion or a protest."
        },
        "noLabel": {
          "en": "Article 220."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 221,
        "text": {
          "en": "Where a people's procuratorate needs to file a procuratorial suggestion or a protest in performing its duty of legal supervision, it may investigate and verify the relevant circumstances from the parties or from persons not involved in the case."
        },
        "noLabel": {
          "en": "Article 221."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 222,
        "text": {
          "en": "For a case in which a people's procuratorate files a protest, the people's court that accepts the protest shall order a retrial within 30 days from the day on which it receives the written protest; where any of the circumstances prescribed in subparagraphs (a) to (e) of Article 211 of this Law applies, the case may be assigned to the people's court at the next lower level for retrial, except where the case has already been retried by that people's court at the next lower level."
        },
        "noLabel": {
          "en": "Article 222."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 223,
        "text": {
          "en": "Where a people's procuratorate decides to file a protest against a judgment, order or mediation agreement of a people's court, it shall prepare a written protest."
        },
        "noLabel": {
          "en": "Article 223."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 224,
        "text": {
          "en": "For a case in which a people's procuratorate files a protest, the people's court shall, in conducting the retrial, notify the people's procuratorate to send personnel to appear in court."
        },
        "noLabel": {
          "en": "Article 224."
        },
        "chapter": {
          "en": "Chapter XVI Procedure for Trial Supervision"
        }
      },
      {
        "no": 225,
        "text": {
          "en": "Where a creditor requests a debtor to pay money or negotiable securities and the following conditions are met, the creditor may apply to the primary people's court with jurisdiction for a payment order:\n(a) there is no other dispute over obligations between the creditor and the debtor; or\n(b) the payment order can be served on the debtor.\nThe application shall state the amount of money or negotiable securities for which payment is requested and the facts and evidence on which the request is based."
        },
        "noLabel": {
          "en": "Article 225."
        },
        "chapter": {
          "en": "Chapter XVII Procedure for Supervision and Urging"
        }
      },
      {
        "no": 226,
        "text": {
          "en": "After a creditor files an application, the people's court shall notify the creditor within five days whether the application is accepted."
        },
        "noLabel": {
          "en": "Article 226."
        },
        "chapter": {
          "en": "Chapter XVII Procedure for Supervision and Urging"
        }
      },
      {
        "no": 227,
        "text": {
          "en": "After accepting an application, the people's court shall, upon examining the facts and evidence provided by the creditor, issue a payment order to the debtor within 15 days from the day of acceptance where the relationship of rights and obligations between the creditor and the debtor is clear and lawful; where the application is not supported, the application shall be rejected by order.\nThe debtor shall discharge its obligations or file a written objection with the people's court within 15 days from the day on which it receives the payment order.\nWhere the debtor neither files an objection nor performs the payment order within the period prescribed in the preceding paragraph, the creditor may apply to the people's court for enforcement."
        },
        "noLabel": {
          "en": "Article 227."
        },
        "chapter": {
          "en": "Chapter XVII Procedure for Supervision and Urging"
        }
      },
      {
        "no": 228,
        "text": {
          "en": "After a people's court receives a written objection filed by the debtor, upon examination, where the objection is upheld, it shall order the termination of the procedure for supervision and urging, and the payment order shall cease to be effective automatically.\nWhere a payment order ceases to be effective, the case shall be transferred to the procedure for litigation, except where the party that applied for the payment order does not agree to file a lawsuit."
        },
        "noLabel": {
          "en": "Article 228."
        },
        "chapter": {
          "en": "Chapter XVII Procedure for Supervision and Urging"
        }
      },
      {
        "no": 229,
        "text": {
          "en": "Where the holder of an instrument that, in accordance with the provisions, may be transferred by endorsement loses the instrument through theft, misplacement or destruction, the holder may apply to the primary people's court at the place of payment of the instrument for the public summons procedure. The provisions of this Chapter shall apply to other matters for which the public summons procedure may be applied in accordance with the provisions of law.\nThe applicant shall submit to the people's court a written application, stating the main contents of the instrument, such as the amount stated on the face of the instrument, the drawer, the holder and the endorser, as well as the grounds for and facts of the application."
        },
        "noLabel": {
          "en": "Article 229."
        },
        "chapter": {
          "en": "Chapter XVIII Procedure for Publicising Public Notice for Assertion of Claims"
        }
      },
      {
        "no": 230,
        "text": {
          "en": "Where a people's court decides to accept an application, it shall simultaneously notify the payor to stop payment, issue a public notice within three days, and urge interested parties to declare their rights. The period of the public summons procedure shall be determined by the people's court in light of the circumstances, but shall not be less than 60 days."
        },
        "noLabel": {
          "en": "Article 230."
        },
        "chapter": {
          "en": "Chapter XVIII Procedure for Publicising Public Notice for Assertion of Claims"
        }
      },
      {
        "no": 231,
        "text": {
          "en": "A payor that has received a notice from a people's court to stop payment shall stop payment until the termination of the public summons procedure.\nDuring the period of the public summons procedure, an act of transferring the rights under an instrument shall be invalid."
        },
        "noLabel": {
          "en": "Article 231."
        },
        "chapter": {
          "en": "Chapter XVIII Procedure for Publicising Public Notice for Assertion of Claims"
        }
      },
      {
        "no": 232,
        "text": {
          "en": "An interested party shall make a declaration to the people's court within the period of the public summons procedure.\nAfter a people's court receives the declaration of an interested party, it shall order the termination of the public summons procedure and notify the applicant and the payor.\nThe applicant or the declarant may file a lawsuit with the people's court."
        },
        "noLabel": {
          "en": "Article 232."
        },
        "chapter": {
          "en": "Chapter XVIII Procedure for Publicising Public Notice for Assertion of Claims"
        }
      },
      {
        "no": 233,
        "text": {
          "en": "Where no person has made a declaration, the people's court shall, upon the application of the applicant, render a judgment declaring the instrument invalid. The judgment shall be publicly announced and the payor shall be notified. From the day of the public announcement of the judgment, the applicant shall have the right to claim payment from the payor."
        },
        "noLabel": {
          "en": "Article 233."
        },
        "chapter": {
          "en": "Chapter XVIII Procedure for Publicising Public Notice for Assertion of Claims"
        }
      },
      {
        "no": 234,
        "text": {
          "en": "Where an interested party, for a justifiable reason, is unable to make a declaration to the people's court before judgment, the interested party may, within one year from the day on which it knows or should have known of the public announcement of the judgment, file a lawsuit with the people's court that rendered the judgment."
        },
        "noLabel": {
          "en": "Article 234."
        },
        "chapter": {
          "en": "Chapter XVIII Procedure for Publicising Public Notice for Assertion of Claims"
        }
      },
      {
        "no": 235,
        "text": {
          "en": "A legally effective civil judgment or order, and the property part of a criminal judgment or order, shall be enforced by the people's court of first instance or by the people's court, at the same level as the people's court of first instance, at the place where the property to be enforced is located.\nOther legal documents which are to be enforced by a people's court as provided by law shall be enforced by the people's court at the place of the domicile of the person subject to enforcement or at the place where the property to be enforced is located."
        },
        "noLabel": {
          "en": "Article 235."
        },
        "chapter": {
          "en": "Chapter XIX General Provisions"
        }
      },
      {
        "no": 236,
        "text": {
          "en": "Where a party or an interested party considers that an act of enforcement violates the provisions of law, it may file a written objection with the people's court responsible for the enforcement. Where a party or an interested party files a written objection, the people's court shall examine the objection within 15 days from the day on which it receives the written objection; where the objection is upheld, the act of enforcement shall be set aside or corrected by order; where the objection is not upheld, the objection shall be rejected by order. Where a party or an interested party refuses to accept the order, it may apply for reconsideration to the people's court at the next higher level within 10 days from the day on which the order is served."
        },
        "noLabel": {
          "en": "Article 236."
        },
        "chapter": {
          "en": "Chapter XIX General Provisions"
        }
      },
      {
        "no": 237,
        "text": {
          "en": "Where a people's court has failed to conduct enforcement for more than six months from the day on which it receives the written application for enforcement, the applicant for enforcement may apply for enforcement to the people's court at the next higher level. Upon examination, the people's court at the next higher level may order the original people's court to conduct enforcement within a specified time limit, and may decide to conduct the enforcement itself or to order another people's court to conduct the enforcement."
        },
        "noLabel": {
          "en": "Article 237."
        },
        "chapter": {
          "en": "Chapter XIX General Provisions"
        }
      },
      {
        "no": 238,
        "text": {
          "en": "In the course of enforcement, where a person not involved in the case files a written objection to the subject matter of enforcement, the people's court shall examine the objection within 15 days from the day on which it receives the written objection; where the objection is upheld, the enforcement against the subject matter shall be stayed by order; where the objection is not upheld, the objection shall be rejected by order. Where a person not involved in the case or a party refuses to accept the order and considers that the original judgment or order is erroneous, the matter shall be handled under the procedure for trial supervision; where the matter is unrelated to the original judgment or order, the person or the party may file a lawsuit with the people's court within 15 days from the day on which the order is served."
        },
        "noLabel": {
          "en": "Article 238."
        },
        "chapter": {
          "en": "Chapter XIX General Provisions"
        }
      },
      {
        "no": 239,
        "text": {
          "en": "Enforcement shall be carried out by an enforcement officer.\nWhen a compulsory enforcement measure is adopted, the enforcement officer shall produce credentials. Upon the completion of enforcement, a record of the enforcement shall be made, and the relevant persons present shall sign or affix their seals to it.\nA people's court may establish an enforcement body as required."
        },
        "noLabel": {
          "en": "Article 239."
        },
        "chapter": {
          "en": "Chapter XIX General Provisions"
        }
      },
      {
        "no": 240,
        "text": {
          "en": "Where the person subject to enforcement or the property to be enforced is located in another locality, the enforcement may be entrusted to the local people's court for execution on its behalf. Upon receiving the letter of entrustment, the entrusted people's court must commence the enforcement within 15 days and shall not refuse to do so. Upon the completion of the enforcement, the result of the enforcement shall be reported in writing to the entrusting people's court without delay; where the enforcement has not been completed within 30 days, the state of the enforcement shall also be reported in writing to the entrusting people's court.\nWhere the entrusted people's court fails to commence the enforcement within 15 days from the day on which it receives the letter of entrustment, the entrusting people's court may request the people's court at a higher level than the entrusted people's court to order the entrusted people's court to conduct the enforcement."
        },
        "noLabel": {
          "en": "Article 240."
        },
        "chapter": {
          "en": "Chapter XIX General Provisions"
        }
      },
      {
        "no": 241,
        "text": {
          "en": "Where, in the course of enforcement, the two parties reach a settlement agreement on their own, the execution officer shall record the contents of the agreement in the record, and the two parties shall sign or affix their seals to it.\nWhere the applicant for enforcement has reached a settlement agreement with the person subject to enforcement through fraud or duress, or a party fails to perform the settlement agreement, the people's court may, upon the application of a party, resume enforcement of the original effective legal document."
        },
        "noLabel": {
          "en": "Article 241."
        },
        "chapter": {
          "en": "Chapter XIX General Provisions"
        }
      },
      {
        "no": 242,
        "text": {
          "en": "Where, in the course of enforcement, the person subject to enforcement provides security to the people's court and the applicant for enforcement consents, the people's court may order a deferment of enforcement and the period of such deferment. Where the person subject to enforcement still fails to perform upon expiry of the period, the people's court shall have the power to enforce the property given as security by the person subject to enforcement or the property of the person providing the security."
        },
        "noLabel": {
          "en": "Article 242."
        },
        "chapter": {
          "en": "Chapter XIX General Provisions"
        }
      },
      {
        "no": 243,
        "text": {
          "en": "Where the citizen who is the person subject to enforcement dies, the debt shall be repaid out of his or her estate. Where the legal person or any other organisation that is the person subject to enforcement terminates, the obligations shall be performed by the successor to its rights and obligations."
        },
        "noLabel": {
          "en": "Article 243."
        },
        "chapter": {
          "en": "Chapter XIX General Provisions"
        }
      },
      {
        "no": 244,
        "text": {
          "en": "Where, after the completion of enforcement, the judgment, order or other legal document on the basis of which the enforcement was carried out is found to be erroneous and is set aside by a people's court, the people's court shall make an order in respect of the property already enforced, directing the person who has obtained the property to return it; where the return is refused, compulsory enforcement shall be carried out."
        },
        "noLabel": {
          "en": "Article 244."
        },
        "chapter": {
          "en": "Chapter XIX General Provisions"
        }
      },
      {
        "no": 245,
        "text": {
          "en": "The enforcement of a written mediation agreement made by a people's court shall be governed by the provisions of this Part."
        },
        "noLabel": {
          "en": "Article 245."
        },
        "chapter": {
          "en": "Chapter XIX General Provisions"
        }
      },
      {
        "no": 246,
        "text": {
          "en": "The people's procuratorates shall have the power to exercise legal supervision over civil enforcement activities."
        },
        "noLabel": {
          "en": "Article 246."
        },
        "chapter": {
          "en": "Chapter XIX General Provisions"
        }
      },
      {
        "no": 247,
        "text": {
          "en": "A legally effective civil judgment or order must be performed by the parties. Where one party refuses to perform it, the other party may apply to a people's court for enforcement, or the enforcement may be referred by a judge to the execution officer for carrying out.\nA written mediation agreement or any other legal document that shall be enforced by a people's court must be performed by the parties. Where one party refuses to perform it, the other party may apply to a people's court for enforcement."
        },
        "noLabel": {
          "en": "Article 247."
        },
        "chapter": {
          "en": "Chapter XX Application and Transfer for Execution"
        }
      },
      {
        "no": 248,
        "text": {
          "en": "Where one party fails to perform an award of an arbitral institution established in accordance with the law, the other party may apply to the people's court with jurisdiction for enforcement. The people's court that receives the application shall enforce the award.\nWhere the respondent adduces evidence proving that the arbitral award falls under any of the following circumstances, the people's court shall, upon examination and verification by a collegial panel, order that the award not be enforced:\n(a) the parties have not stipulated an arbitration clause in the contract or have not reached a written arbitration agreement afterwards;\n(b) the matters decided fall outside the scope of the arbitration agreement or the arbitral institution has no power to arbitrate them;\n(c) the composition of the arbitral tribunal or the arbitration procedure contravenes the statutory procedure;\n(d) the evidence on which the award is based is forged;\n(e) the opposing party has concealed from the arbitral institution evidence sufficient to affect an impartial award; or\n(f) the arbitrators have committed embezzlement, accepted bribes, engaged in malpractices for personal gain or rendered an arbitral award by bending the law in arbitrating the case.\nWhere a people's court finds that enforcement of the award would contravene the public interest of society, it shall order that the award not be enforced.\nThe order shall be served on both parties and the arbitral institution.\nWhere an arbitral award is ordered not to be enforced by a people's court, the parties may, in accordance with the written arbitration agreement reached by them, re-apply for arbitration or file a lawsuit with a people's court."
        },
        "noLabel": {
          "en": "Article 248."
        },
        "chapter": {
          "en": "Chapter XX Application and Transfer for Execution"
        }
      },
      {
        "no": 249,
        "text": {
          "en": "Where one party fails to perform a creditor's document to which a notarial office has, in accordance with the law, granted compulsory enforceability, the other party may apply to the people's court with jurisdiction for enforcement, and the people's court that receives the application shall enforce the document.\nWhere a notarised creditor's document is found to be erroneous, the people's court shall order that it not be enforced and serve the order on both parties and the notarial office."
        },
        "noLabel": {
          "en": "Article 249."
        },
        "chapter": {
          "en": "Chapter XX Application and Transfer for Execution"
        }
      },
      {
        "no": 250,
        "text": {
          "en": "The period for applying for enforcement is two years. The suspension and interruption of the time limit for application for enforcement shall be governed by the provisions of the law on the suspension and interruption of the limitation period.\nThe period prescribed in the preceding paragraph shall be calculated from the last day of the period for performance specified in the legal document; where the legal document provides for performance in instalments, it shall be calculated from the day on which the time limit for performance of the last instalment expires; where the legal document does not specify a period for performance, it shall be calculated from the day on which the legal document takes effect."
        },
        "noLabel": {
          "en": "Article 250."
        },
        "chapter": {
          "en": "Chapter XX Application and Transfer for Execution"
        }
      },
      {
        "no": 251,
        "text": {
          "en": "Upon receiving an application for enforcement or a referral for enforcement, the execution officer shall issue a notice of enforcement to the person subject to enforcement and may immediately adopt compulsory enforcement measures."
        },
        "noLabel": {
          "en": "Article 251."
        },
        "chapter": {
          "en": "Chapter XX Application and Transfer for Execution"
        }
      },
      {
        "no": 252,
        "text": {
          "en": "Where the person subject to enforcement fails to perform the obligations determined in the legal document in accordance with the notice of enforcement, he, she or it shall report the current property situation and the property situation for the year preceding the day of receipt of the notice of enforcement. Where the person subject to enforcement refuses to make a report or makes a false report, the people's court may, in light of the seriousness of the circumstances, impose a fine or detention on the person subject to enforcement or his, her or its statutory agent, or on the principal person in charge of a relevant unit or the person directly responsible."
        },
        "noLabel": {
          "en": "Article 252."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 253,
        "text": {
          "en": "Where the person subject to enforcement fails to perform the obligations determined in the legal document in accordance with the notice of enforcement, the people's court shall have the power to inquire with relevant units into the deposits, bonds, shares, fund units and other property of the person subject to enforcement. The people's court shall have the power, according to the different circumstances, to seize, freeze, transfer or convert into money the property of the person subject to enforcement. The property inquired into, seized, frozen, transferred or converted into money by the people's court shall not exceed the scope of the obligations that the person subject to enforcement shall perform.\nWhere a people's court decides to seize, freeze, transfer or convert into money property, it shall make an order and issue a notice of assistance in enforcement, and the relevant unit must handle the matter accordingly."
        },
        "noLabel": {
          "en": "Article 253."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 254,
        "text": {
          "en": "Where the person subject to enforcement fails to perform the obligations determined in the legal document in accordance with the notice of enforcement, the people's court shall have the power to withhold and collect the portion of the income of the person subject to enforcement corresponding to the obligations that he, she or it shall perform, provided that the necessary living expenses of the person subject to enforcement and the family members whom he or she supports shall be retained.\nWhere a people's court withholds or collects income, it shall make an order and issue a notice of assistance in enforcement, and the unit where the person subject to enforcement works, the bank, the credit cooperative and any other unit engaged in savings business must handle the matter accordingly."
        },
        "noLabel": {
          "en": "Article 254."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 255,
        "text": {
          "en": "Where the person subject to enforcement fails to perform the obligations determined in the legal document in accordance with the notice of enforcement, the people's court shall have the power to seal up, seize, freeze, auction or sell the portion of the property of the person subject to enforcement corresponding to the obligations that he, she or it shall perform, provided that the necessities of life of the person subject to enforcement and the family members whom he or she supports shall be retained.\nWhere the measures prescribed in the preceding paragraph are adopted, the people's court shall make an order."
        },
        "noLabel": {
          "en": "Article 255."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 256,
        "text": {
          "en": "Where a people's court seals up or seizes property, it shall notify the person subject to enforcement or his or her adult family members to be present where the person subject to enforcement is a citizen, and shall notify the legal representative or the principal person in charge to be present where the person subject to enforcement is a legal person or any other organisation. A refusal to be present shall not affect the enforcement. Where the person subject to enforcement is a citizen, the unit where he or she works or the grassroots organisation at the place where the property is located shall send a person to participate.\nFor property that has been sealed up or seized, the execution officer must make an inventory; after the persons present have signed or affixed their seals to it, one copy shall be given to the person subject to enforcement. Where the person subject to enforcement is a citizen, a copy may also be given to his or her adult family members."
        },
        "noLabel": {
          "en": "Article 256."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 257,
        "text": {
          "en": "For property that has been sealed up, the execution officer may designate the person subject to enforcement to be responsible for its safekeeping. Losses caused by the fault of the person subject to enforcement shall be borne by the person subject to enforcement."
        },
        "noLabel": {
          "en": "Article 257."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 258,
        "text": {
          "en": "After property has been sealed up or seized, the execution officer shall order the person subject to enforcement to perform the obligations determined in the legal document within a designated period. Where the person subject to enforcement fails to perform upon expiry of the period, the people's court shall auction the sealed-up or seized property; where the property is unsuitable for auction or both parties agree that no auction shall be conducted, the people's court may entrust a relevant unit to sell it or sell it itself. Articles whose free trading is prohibited by the State shall be purchased by a relevant unit at the price prescribed by the State."
        },
        "noLabel": {
          "en": "Article 258."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 259,
        "text": {
          "en": "Where the person subject to enforcement fails to perform the obligations determined in the legal document and conceals property, the people's court shall have the power to issue a search warrant and search the person subject to enforcement, his or her dwelling or the place where the property is concealed.\nThe search warrant for the measure prescribed in the preceding paragraph shall be issued by the president of the people's court."
        },
        "noLabel": {
          "en": "Article 259."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 260,
        "text": {
          "en": "Property or negotiable securities designated for delivery in a legal document shall be delivered by the execution officer face to face after summoning both parties, or transmitted by the execution officer, and shall be signed for by the person to whom delivery is made.\nWhere a relevant unit holds the said property or negotiable securities, it shall transmit them in accordance with the notice of assistance in enforcement issued by the people's court, and they shall be signed for by the person to whom delivery is made.\nWhere a relevant citizen holds the said property or negotiable securities, the people's court shall notify him or her to hand them over. Where the handover is refused, compulsory enforcement shall be carried out."
        },
        "noLabel": {
          "en": "Article 260."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 261,
        "text": {
          "en": "For forced eviction from a house or forced surrender of land, the president of the people's court shall issue an announcement ordering the person subject to enforcement to perform within a designated period. Where the person subject to enforcement fails to perform upon expiry of the period, the execution officer shall carry out compulsory enforcement.\nIn the course of compulsory enforcement, the person subject to enforcement or his or her adult family members shall be notified to be present where the person subject to enforcement is a citizen, and the legal representative or the principal person in charge shall be notified to be present where the person subject to enforcement is a legal person or any other organisation. A refusal to be present shall not affect the enforcement. Where the person subject to enforcement is a citizen, the unit where he or she works or the grassroots organisation at the place where the house or land is located shall send a person to participate. The execution officer shall record the circumstances of the compulsory enforcement in the record, and the persons present shall sign or affix their seals to it.\nProperty removed as a result of the forced eviction from a house shall be transported by a person sent by the people's court to a designated place and handed over to the person subject to enforcement. Where the person subject to enforcement is a citizen, it may also be handed over to his or her adult family members. Losses caused by a refusal to accept the property shall be borne by the person subject to enforcement."
        },
        "noLabel": {
          "en": "Article 261."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 262,
        "text": {
          "en": "Where, in the course of enforcement, procedures for the transfer of certificates relating to property rights need to be gone through, the people's court may issue a notice of assistance in enforcement to relevant units, and the relevant units must handle the matter accordingly."
        },
        "noLabel": {
          "en": "Article 262."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 263,
        "text": {
          "en": "Where the person subject to enforcement fails to perform, in accordance with the notice of enforcement, the acts designated in the judgment, order or other legal document, the people's court may carry out compulsory enforcement or entrust a relevant unit or another person to complete the acts, and the expenses shall be borne by the person subject to enforcement."
        },
        "noLabel": {
          "en": "Article 263."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 264,
        "text": {
          "en": "Where the person subject to enforcement fails to perform the obligation to pay money within the period designated in the judgment, order or other legal document, he, she or it shall pay doubled interest on the debt for the period of delayed performance. Where the person subject to enforcement fails to perform other obligations within the period designated in the judgment, order or other legal document, he, she or it shall pay a penalty for delayed performance."
        },
        "noLabel": {
          "en": "Article 264."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 265,
        "text": {
          "en": "Where, after the people's court has adopted the enforcement measures prescribed in Articles 253, 254 and 255 of this Law, the person subject to enforcement is still unable to repay the debt, he, she or it shall continue to perform the obligations. Where the creditor discovers that the person subject to enforcement has other property, the creditor may at any time request the people's court to enforce the obligations."
        },
        "noLabel": {
          "en": "Article 265."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 266,
        "text": {
          "en": "Where the person subject to enforcement fails to perform the obligations determined in the legal document, the people's court may adopt against him, her or it, or notify relevant units to assist in adopting, measures such as restricting exit from the territory, recording information on the non-performance of obligations in the credit reporting system and publishing information on the non-performance of obligations through the media, as well as other measures prescribed by law."
        },
        "noLabel": {
          "en": "Article 266."
        },
        "chapter": {
          "en": "Chapter XXI Execution Measures"
        }
      },
      {
        "no": 267,
        "text": {
          "en": "Where any of the following circumstances exists, the people's court shall order the suspension of enforcement:\n(a) the applicant indicates that enforcement may be deferred;\n(b) a person not involved in the case raises a well-founded objection to the object of enforcement;\n(c) a citizen who is a party dies and it is necessary to wait for a successor to succeed to the rights or assume the obligations;\n(d) a legal person or any other organisation that is a party terminates and the successor to its rights and obligations has not yet been determined; or\n(e) any other circumstance in which the people's court finds that enforcement should be suspended.\nAfter the circumstance of suspension has disappeared, enforcement shall be resumed."
        },
        "noLabel": {
          "en": "Article 267."
        },
        "chapter": {
          "en": "Chapter XXII Suspension and Termination of Execution"
        }
      },
      {
        "no": 268,
        "text": {
          "en": "Where any of the following circumstances exists, the people's court shall order the termination of enforcement:\n(a) the applicant withdraws the application;\n(b) the legal document on the basis of which enforcement is carried out is set aside;\n(c) the citizen who is the person subject to enforcement dies, there is no estate available for enforcement and there is no person to assume the obligations;\n(d) the obligee in a case for the recovery of the expenses for the support of elders, of maintenance or of child support dies;\n(e) the citizen who is the person subject to enforcement is unable to repay the loan due to difficulties in living, has no source of income and has lost the ability to work; or\n(f) any other circumstance in which the people's court finds that enforcement should be terminated."
        },
        "noLabel": {
          "en": "Article 268."
        },
        "chapter": {
          "en": "Chapter XXII Suspension and Termination of Execution"
        }
      },
      {
        "no": 269,
        "text": {
          "en": "An order for the suspension or termination of enforcement shall take effect immediately upon service on the parties."
        },
        "noLabel": {
          "en": "Article 269."
        },
        "chapter": {
          "en": "Chapter XXII Suspension and Termination of Execution"
        }
      },
      {
        "no": 270,
        "text": {
          "en": "Foreign-related civil litigation conducted within the territory of the People's Republic of China shall be governed by the provisions of this Part. Where this Part contains no provisions, the other relevant provisions of this Law shall apply."
        },
        "noLabel": {
          "en": "Article 270."
        },
        "chapter": {
          "en": "Chapter XXIII General Principles"
        }
      },
      {
        "no": 271,
        "text": {
          "en": "Where an international treaty concluded or acceded to by the People's Republic of China contains provisions different from those of this Law, the provisions of that international treaty shall apply, except for the clauses to which the People's Republic of China has declared reservations."
        },
        "noLabel": {
          "en": "Article 271."
        },
        "chapter": {
          "en": "Chapter XXIII General Principles"
        }
      },
      {
        "no": 272,
        "text": {
          "en": "Civil litigation instituted against foreigners, foreign organisations or international organisations enjoying diplomatic privileges and immunities shall be conducted in accordance with the relevant laws of the People's Republic of China and the international treaties concluded or acceded to by the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 272."
        },
        "chapter": {
          "en": "Chapter XXIII General Principles"
        }
      },
      {
        "no": 273,
        "text": {
          "en": "People's courts shall use the commonly used language and script of the People's Republic of China in trying foreign-related civil cases. Where a party requests interpretation or translation, it may be provided, and the costs shall be borne by the party."
        },
        "noLabel": {
          "en": "Article 273."
        },
        "chapter": {
          "en": "Chapter XXIII General Principles"
        }
      },
      {
        "no": 274,
        "text": {
          "en": "Foreigners, stateless persons, foreign enterprises and organisations that file a lawsuit or respond to an action in a people's court and need to entrust lawyers to act as agents ad litem must entrust lawyers of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 274."
        },
        "chapter": {
          "en": "Chapter XXIII General Principles"
        }
      },
      {
        "no": 275,
        "text": {
          "en": "A power of attorney sent or delivered from outside the territory of the People's Republic of China by a foreigner, stateless person, foreign enterprise or organisation that has no domicile within the territory of the People's Republic of China and entrusts a lawyer of the People's Republic of China or another person to act as agent ad litem shall be notarised by a notarial office of the country where it is located and legalised by the embassy or consulate of the People's Republic of China in that country, or shall go through the certification procedures prescribed in the relevant treaties concluded between the People's Republic of China and that country, before it becomes effective."
        },
        "noLabel": {
          "en": "Article 275."
        },
        "chapter": {
          "en": "Chapter XXIII General Principles"
        }
      },
      {
        "no": 276,
        "text": {
          "en": "For a foreign-related civil dispute, an action other than one concerning personal relations instituted against a defendant that has no domicile within the territory of the People's Republic of China may be under the jurisdiction of the people's court of the place where the contract is signed, the place where the contract is performed, the place where the subject matter of the action is located, the place where property available for seizure is located, the place where the tort is committed or the domicile of the representative office, if any of such places is within the territory of the People's Republic of China.\nIn addition to the provisions of the preceding paragraph, where a foreign-related civil dispute has other appropriate connections with the People's Republic of China, it may be under the jurisdiction of a people's court."
        },
        "noLabel": {
          "en": "Article 276."
        },
        "chapter": {
          "en": "Chapter XXIV Jurisdiction"
        }
      },
      {
        "no": 277,
        "text": {
          "en": "Where the parties to a foreign-related civil dispute choose the jurisdiction of a people's court by written agreement, the dispute may be under the jurisdiction of the people's court."
        },
        "noLabel": {
          "en": "Article 277."
        },
        "chapter": {
          "en": "Chapter XXIV Jurisdiction"
        }
      },
      {
        "no": 278,
        "text": {
          "en": "Where the parties do not raise a jurisdictional objection and respond to the action and file a defence or file a counterclaim, the people's court shall be deemed to have jurisdiction."
        },
        "noLabel": {
          "en": "Article 278."
        },
        "chapter": {
          "en": "Chapter XXIV Jurisdiction"
        }
      },
      {
        "no": 279,
        "text": {
          "en": "People's courts shall have exclusive jurisdiction over the following civil cases:\n(a) actions arising from disputes over the establishment, dissolution or liquidation of a legal person or other organisation established within the territory of the People's Republic of China, and over the validity of resolutions made by such legal person or other organisation;\n(b) actions arising from disputes relating to the validity of intellectual property rights examined and granted within the territory of the People's Republic of China;\n(c) actions arising from disputes over the performance within the territory of the People's Republic of China of contracts for Sino-foreign equity joint ventures, contracts for Sino-foreign cooperative joint ventures, or contracts for Sino-foreign cooperative exploration and development of natural resources."
        },
        "noLabel": {
          "en": "Article 279."
        },
        "chapter": {
          "en": "Chapter XXIV Jurisdiction"
        }
      },
      {
        "no": 280,
        "text": {
          "en": "Where, in respect of the same dispute between the parties, one party files a lawsuit with a foreign court and the other party files a lawsuit with a people's court, or one party files a lawsuit with both a foreign court and a people's court, the people's court may accept the case if it has jurisdiction in accordance with this Law. Where the parties have concluded an exclusive choice of court agreement selecting the jurisdiction of a foreign court, and the agreement does not violate the provisions of this Law on exclusive jurisdiction and does not involve the sovereignty, security or public interest of society of the People's Republic of China, the people's court may order that the case not be accepted; where the case has already been accepted, it shall order the rejection of the lawsuit."
        },
        "noLabel": {
          "en": "Article 280."
        },
        "chapter": {
          "en": "Chapter XXIV Jurisdiction"
        }
      },
      {
        "no": 281,
        "text": {
          "en": "After a people's court has accepted a case in accordance with the provisions of the preceding Article, where a party applies in writing to the people's court to stay the proceedings on the ground that the foreign court has already accepted the case before the people's court, the people's court may order a stay of the proceedings, except under any of the following circumstances:\n(a) the parties have chosen the jurisdiction of the people's court by agreement, or the dispute falls under the exclusive jurisdiction of the people's court;\n(b) trial by the people's court is obviously more convenient.\nWhere the foreign court has not taken the necessary measures to try the case, or has not concluded the trial within a reasonable period, the people's court shall, upon the written application of a party, resume the proceedings.\nWhere a legally effective judgment or order made by a foreign court has been wholly or partially recognised by a people's court, and a party files a lawsuit again with a people's court in respect of the part already recognised, the people's court shall order that the case not be accepted; where the case has already been accepted, it shall order the rejection of the lawsuit."
        },
        "noLabel": {
          "en": "Article 281."
        },
        "chapter": {
          "en": "Chapter XXIV Jurisdiction"
        }
      },
      {
        "no": 282,
        "text": {
          "en": "Where, in a foreign-related civil case accepted by a people's court, the defendant raises a jurisdictional objection and all of the following circumstances exist at the same time, the people's court may order the rejection of the lawsuit and inform the plaintiff to file a lawsuit with a more convenient foreign court:\n(a) the basic facts of the dispute did not occur within the territory of the People's Republic of China, and it is obviously inconvenient for the people's court to try the case and for the parties to participate in the proceedings;\n(b) there is no agreement between the parties choosing the jurisdiction of the people's court;\n(c) the case does not fall under the exclusive jurisdiction of the people's court;\n(d) the case does not involve the sovereignty, security or public interest of society of the People's Republic of China;\n(e) it is more convenient for the foreign court to try the case.\nWhere, after the order rejecting the lawsuit is made, the foreign court declines to exercise jurisdiction over the dispute, or fails to take the necessary measures to try the case, or fails to conclude the trial within a reasonable period, and a party files a lawsuit again with the people's court, the people's court shall accept the case."
        },
        "noLabel": {
          "en": "Article 282."
        },
        "chapter": {
          "en": "Chapter XXIV Jurisdiction"
        }
      },
      {
        "no": 283,
        "text": {
          "en": "Where a people's court serves litigation documents on a party that has no domicile within the territory of the People's Republic of China, it may adopt the following methods:\n(a) service in the manner prescribed in the international treaties concluded or acceded to by both the country where the person to be served is located and the People's Republic of China;\n(b) service through diplomatic channels;\n(c) in the case of a person to be served who has the nationality of the People's Republic of China, service may be entrusted to the embassy or consulate of the People's Republic of China in the country where the person to be served is located;\n(d) service on the agent ad litem entrusted by the person to be served in the case;\n(e) service on a wholly-owned enterprise, representative office or branch established by the person to be served within the territory of the People's Republic of China, or on a business agent with the authority to accept service;\n(f) where the person to be served is a foreigner or a stateless person who serves as the legal representative or principal person in charge of a legal person or other organisation established within the territory of the People's Republic of China and is a co-defendant with that legal person or other organisation, service on that legal person or other organisation;\n(g) where the person to be served is a foreign legal person or other organisation and its legal representative or principal person in charge is within the territory of the People's Republic of China, service on its legal representative or principal person in charge;\n(h) where the law of the country where the person to be served is located permits service by post, service may be effected by post; where, three months after the date of posting, the certificate of service has not been returned but it is sufficient to determine from all the circumstances that service has been effected, the date of expiry of that period shall be deemed the date of service;\n(i) service by electronic means capable of confirming receipt by the person to be served, unless prohibited by the law of the country where the person to be served is located;\n(j) service by other means agreed to by the person to be served, unless prohibited by the law of the country where the person to be served is located.\nWhere service cannot be effected by the above methods, service shall be effected by public announcement, and service shall be deemed effected upon the expiry of 60 days from the date of the announcement."
        },
        "noLabel": {
          "en": "Article 283."
        },
        "chapter": {
          "en": "Chapter XXV Service, Investigation and Evidence Collection, and Time Periods"
        }
      },
      {
        "no": 284,
        "text": {
          "en": "Where evidence applied for by a party to be investigated and collected by a people's court is located outside the territory of the People's Republic of China, the people's court may investigate and collect it in the manner prescribed in the international treaties concluded or acceded to by both the country where the evidence is located and the People's Republic of China, or through diplomatic channels.\nWhere the law of the country where the evidence is located does not prohibit it, the people's court may investigate and collect evidence by the following methods:\n(a) in the case of a party or witness who has the nationality of the People's Republic of China, entrust the embassy or consulate of the People's Republic of China in the country where the party or witness is located to obtain the evidence on its behalf;\n(b) with the consent of both parties, obtain evidence through instant messaging tools;\n(c) obtain evidence by other means agreed to by both parties."
        },
        "noLabel": {
          "en": "Article 284."
        },
        "chapter": {
          "en": "Chapter XXV Service, Investigation and Evidence Collection, and Time Periods"
        }
      },
      {
        "no": 285,
        "text": {
          "en": "Where the defendant has no domicile within the territory of the People's Republic of China, the people's court shall serve a copy of the statement of claim on the defendant and notify the defendant to submit a statement of defence within 30 days after receipt of the copy of the statement of claim. Where the defendant applies for an extension, the people's court shall decide whether to grant it."
        },
        "noLabel": {
          "en": "Article 285."
        },
        "chapter": {
          "en": "Chapter XXV Service, Investigation and Evidence Collection, and Time Periods"
        }
      },
      {
        "no": 286,
        "text": {
          "en": "A party that has no domicile within the territory of the People's Republic of China and is dissatisfied with a judgment or order of a people's court of first instance shall have the right to file an appeal within 30 days from the date of service of the written judgment or written order. The appellee shall, within 30 days after receipt of a copy of the written appeal, submit a statement of defence. Where a party is unable to file an appeal or submit a statement of defence within the statutory period and applies for an extension, the people's court shall decide whether to grant it."
        },
        "noLabel": {
          "en": "Article 286."
        },
        "chapter": {
          "en": "Chapter XXV Service, Investigation and Evidence Collection, and Time Periods"
        }
      },
      {
        "no": 287,
        "text": {
          "en": "The time period for a people's court to try a foreign-related civil case shall not be subject to the restrictions prescribed in Articles 152 and 183 of this Law."
        },
        "noLabel": {
          "en": "Article 287."
        },
        "chapter": {
          "en": "Chapter XXV Service, Investigation and Evidence Collection, and Time Periods"
        }
      },
      {
        "no": 288,
        "text": {
          "en": "Where a dispute arising in foreign-related economic and trade, transport or maritime matters is submitted for arbitration to an arbitral institution of the People's Republic of China handling cases involving foreign elements or to another arbitral institution, in accordance with an arbitration clause in the contract or a written arbitration agreement reached afterwards, the parties shall not file a lawsuit with a people's court.\nWhere the parties have not stipulated an arbitration clause in the contract or have not reached a written arbitration agreement afterwards, they may file a lawsuit with a people's court."
        },
        "noLabel": {
          "en": "Article 288."
        },
        "chapter": {
          "en": "Chapter XXVI Arbitration"
        }
      },
      {
        "no": 289,
        "text": {
          "en": "Where a party applies for preservation, the arbitral institution of the People's Republic of China handling cases involving foreign elements shall submit the party's application to the intermediate people's court at the domicile of the respondent or the place where the property is located for an order."
        },
        "noLabel": {
          "en": "Article 289."
        },
        "chapter": {
          "en": "Chapter XXVI Arbitration"
        }
      },
      {
        "no": 290,
        "text": {
          "en": "Where an award has been made by an arbitral institution of the People's Republic of China handling cases involving foreign elements, the parties shall not file a lawsuit with a people's court. Where one party fails to perform the arbitral award, the other party may apply for enforcement to the intermediate people's court at the domicile of the respondent or the place where the property is located."
        },
        "noLabel": {
          "en": "Article 290."
        },
        "chapter": {
          "en": "Chapter XXVI Arbitration"
        }
      },
      {
        "no": 291,
        "text": {
          "en": "Where, in respect of an award made by an arbitral institution of the People's Republic of China handling cases involving foreign elements, the respondent adduces evidence proving that the arbitral award falls under any of the following circumstances, the people's court shall, upon examination and verification by a collegial panel, order that the award not be enforced:\n(a) the parties have not stipulated an arbitration clause in the contract or have not reached a written arbitration agreement afterwards;\n(b) the respondent was not notified of the appointment of an arbitrator or of the arbitral proceedings, or was unable to present its case for reasons not attributable to the respondent;\n(c) the composition of the arbitral tribunal or the arbitral procedure was not in conformity with the arbitration rules;\n(d) the matters decided fall outside the scope of the arbitration agreement or the arbitral institution has no power to arbitrate them.\nWhere a people's court finds that enforcement of the award would contravene the public interest of society, it shall order that the award not be enforced."
        },
        "noLabel": {
          "en": "Article 291."
        },
        "chapter": {
          "en": "Chapter XXVI Arbitration"
        }
      },
      {
        "no": 292,
        "text": {
          "en": "Where an arbitral award is ordered not to be enforced by a people's court, the parties may, in accordance with the written arbitration agreement reached by them, re-apply for arbitration or file a lawsuit with a people's court."
        },
        "noLabel": {
          "en": "Article 292."
        },
        "chapter": {
          "en": "Chapter XXVI Arbitration"
        }
      },
      {
        "no": 293,
        "text": {
          "en": "In accordance with the international treaties concluded or acceded to by the People's Republic of China, or in accordance with the principle of reciprocity, people's courts and foreign courts may request each other to serve documents, investigate and collect evidence and perform other litigation acts on their behalf.\nWhere a matter requested for assistance by a foreign court is detrimental to the sovereignty, security or public interest of society of the People's Republic of China, the people's court shall not carry it out."
        },
        "noLabel": {
          "en": "Article 293."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 294,
        "text": {
          "en": "Requests for and the provision of judicial assistance shall be made through the channels prescribed in the international treaties concluded or acceded to by the People's Republic of China; where there is no treaty relationship, they shall be made through diplomatic channels.\nThe embassy or consulate of a foreign country in the People's Republic of China may serve documents on and investigate and collect evidence from its nationals, provided that it does not violate the laws of the People's Republic of China and does not adopt compulsory measures.\nExcept in the circumstances prescribed in the preceding paragraph, no foreign authority or individual may serve documents or investigate and collect evidence within the territory of the People's Republic of China without the permission of the competent authority of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 294."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 295,
        "text": {
          "en": "The letter of request of a foreign court requesting a people's court to provide judicial assistance and the documents attached thereto shall be accompanied by a Chinese translation or a text in another language prescribed by the international treaty.\nThe letter of request of a people's court requesting a foreign court to provide judicial assistance and the documents attached thereto shall be accompanied by a translation in the language of that country or a text in another language prescribed by the international treaty."
        },
        "noLabel": {
          "en": "Article 295."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 296,
        "text": {
          "en": "A people's court shall provide judicial assistance in accordance with the procedures prescribed by the laws of the People's Republic of China. Where a foreign court requests the adoption of a special method, that special method may also be adopted, provided that the requested special method does not violate the laws of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 296."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 297,
        "text": {
          "en": "Where a legally effective judgment or order made by a people's court is to be enforced and the person subject to enforcement or its property is not within the territory of the People's Republic of China, and a party requests enforcement, the party may directly apply to the competent foreign court for recognition and enforcement, or the people's court may, in accordance with the provisions of the international treaties concluded or acceded to by the People's Republic of China, or in accordance with the principle of reciprocity, request the foreign court to recognise and enforce it.\nWhere a legally effective arbitral award made in accordance with the law within the territory of the People's Republic of China is to be enforced and the person subject to enforcement or its property is not within the territory of the People's Republic of China, the party may directly apply to the competent foreign court for recognition and enforcement."
        },
        "noLabel": {
          "en": "Article 297."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 298,
        "text": {
          "en": "Where a legally effective judgment or order made by a foreign court needs to be recognised and enforced by a people's court, a party may directly apply to the competent intermediate people's court for recognition and enforcement, or the foreign court may, in accordance with the provisions of the international treaties concluded or acceded to by that country and the People's Republic of China, or in accordance with the principle of reciprocity, request the people's court to recognise and enforce it."
        },
        "noLabel": {
          "en": "Article 298."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 299,
        "text": {
          "en": "Where, after examining an application or request for the recognition and enforcement of a legally effective judgment or order made by a foreign court in accordance with the international treaties concluded or acceded to by the People's Republic of China or in accordance with the principle of reciprocity, a people's court considers that it does not violate the fundamental principles of the laws of the People's Republic of China and does not harm the sovereignty, security or public interest of society of the State, the people's court shall order the recognition of its effect; where enforcement is needed, it shall issue an order for enforcement and enforce it in accordance with the relevant provisions of this Law."
        },
        "noLabel": {
          "en": "Article 299."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 300,
        "text": {
          "en": "Where, after examination, a people's court finds that a legally effective judgment or order made by a foreign court for which recognition and enforcement is applied for or requested falls under any of the following circumstances, it shall order that it not be recognised and enforced:\n(a) in accordance with the provisions of Article 301 of this Law, the foreign court has no jurisdiction over the case;\n(b) the respondent was not lawfully summoned, or, although lawfully summoned, was not given a reasonable opportunity to state its case and debate, or a party without capacity for litigation conduct was not properly represented;\n(c) the judgment or order was obtained by fraud;\n(d) a people's court has already made a judgment or order on the same dispute, or has already recognised a judgment or order made by a court of a third country on the same dispute;\n(e) it violates the fundamental principles of the laws of the People's Republic of China or harms the sovereignty, security or public interest of society of the State."
        },
        "noLabel": {
          "en": "Article 300."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 301,
        "text": {
          "en": "A people's court shall find that a foreign court has no jurisdiction over a case under any of the following circumstances:\n(a) the foreign court has no jurisdiction over the case under its own law, or, though it has jurisdiction under its own law, the case has no appropriate connection with the dispute involved;\n(b) the jurisdiction exercised violates the provisions of this Law on exclusive jurisdiction; or\n(c) the jurisdiction exercised violates the agreement of the parties on the exclusive choice of court jurisdiction."
        },
        "noLabel": {
          "en": "Article 301."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 302,
        "text": {
          "en": "Where a party applies to a people's court for recognition and enforcement of a legally effective judgment or order rendered by a foreign court, and the dispute involved in the judgment or order is the same dispute as the one under trial by the people's court, the people's court may order the suspension of the litigation.\nWhere a legally effective judgment or order rendered by a foreign court does not meet the conditions for recognition prescribed by this Law, the people's court shall order non-recognition and non-enforcement and resume the suspended litigation; where the judgment or order meets the conditions for recognition prescribed by this Law, the people's court shall order recognition of its effect; where enforcement is necessary, the people's court shall issue a writ of enforcement and enforce the judgment or order in accordance with the relevant provisions of this Law; as to the suspended litigation, the people's court shall order the dismissal of the action."
        },
        "noLabel": {
          "en": "Article 302."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 303,
        "text": {
          "en": "Where a party disagrees with an order on recognition and enforcement or on non-recognition and non-enforcement, the party may, within 10 days from the date of service of the order, apply for reconsideration to the people's court at the next higher level."
        },
        "noLabel": {
          "en": "Article 303."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 304,
        "text": {
          "en": "Where an arbitration award rendered outside the territory of the People's Republic of China needs recognition and enforcement by a people's court, the party may directly apply to the intermediate people's court at the place of domicile of the party against whom enforcement is sought or at the place where the property of that party is located. Where the domicile of the party against whom enforcement is sought or the property of that party is not located within the territory of the People's Republic of China, the party may apply to the intermediate people's court at the place of domicile of the applicant or at a place having an appropriate connection with the dispute over the award. The people's court shall handle the matter in accordance with the international treaties concluded or acceded to by the People's Republic of China, or on the principle of reciprocity."
        },
        "noLabel": {
          "en": "Article 304."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 305,
        "text": {
          "en": "Civil litigation involving a foreign State shall be governed by the legal provisions of the People's Republic of China on the immunity of foreign States; where the relevant laws make no provisions, this Law shall apply."
        },
        "noLabel": {
          "en": "Article 305."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      },
      {
        "no": 306,
        "text": {
          "en": "This Law shall come into force on the date of promulgation, and the Civil Procedure Law of the People's Republic of China (for Trial Implementation) shall be repealed at the same time."
        },
        "noLabel": {
          "en": "Article 306."
        },
        "chapter": {
          "en": "Chapter XXVII Judicial Assistance"
        }
      }
    ]
  };

})(typeof window !== 'undefined' ? window : globalThis);